                chapterNameArabic = "الأربعون النووية",
                chapterNameUrdu = "امام نووی کی چالیس احادیث مبارکہ",
                hadithNumber = "5",
                arabicText = "عَنْ أُمِّ الْمُؤْمِنِينَ أُمِّ عَبْدِ اللَّهِ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا، قَالَتْ: قَالَ: رَسُولُ اللَّهِ صلى الله عليه و سلم مَنْ أَحْدَثَ فِي أَمْرِنَا هَذَا مَا لَيْسَ مِنْهُ فَهُوَ رَدٌّ [رَوَاهُ الْبُخَارِيُّ] ،[وَمُسْلِمٌ] وَفِي رِوَايَةٍ لِمُسْلِمٍ: مَنْ عَمِلَ عَمَلًا لَيْسَ عَلَيْهِ أَمْرُنَا فَهُوَ رَدٌّ",
                urduTranslation = "ام المؤمنین حضرت عائشہ رضی اللہ عنہا سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: جس نے ہمارے اس دین میں کوئی ایسی نئی بات ایجاد کی جو اس میں سے نہیں ہے تو وہ مردود ہے۔ (صحیح بخاری و صحیح مسلم)",
                englishTranslation = "On the authority of the mother of the faithful, Aisha (ra), who said: The Messenger of Allah (ﷺ) said, “He who innovates something in this matter of ours (i.e., Islam) that is not of it will have it rejected (by Allah).” [Bukhari & Muslim] In another version in Muslim it reads: “He who does an act which we have not commanded, will have it rejected (by Allah).”",
                activeTranslation = "ام المؤمنین حضرت عائشہ رضی اللہ عنہا سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: جس نے ہمارے اس دین میں کوئی ایسی نئی بات ایجاد کی جو اس میں سے نہیں ہے تو وہ مردود ہے۔ (صحیح بخاری و صحیح مسلم)"
