                arabicText = "عَنْ أَبِي ذَرٍّ الْغِفَارِيِّ رَضِيَ اللهُ عَنْهُ عَنْ النَّبِيِّ صلى الله عليه و سلم فِيمَا يَرْوِيهِ عَنْ رَبِّهِ تَبَارَكَ وَتَعَالَى، أَنَّهُ قَالَ: يَا عِبَادِي: إنِّي حَرَّمْت الظُّلْمَ عَلَى نَفْسِي، وَجَعَلْته بَيْنَكُمْ مُحَرَّمًا؛ فَلَا تَظَالَمُوا. يَا عِبَادِي! كُلُّكُمْ ضَالٌّ إلَّا مَنْ هَدَيْته، فَاسْتَهْدُونِي أَهْدِكُمْ. يَا عِبَادِي! كُلُّكُمْ جَائِعٌ إلَّا مَنْ أَطْعَمْته، فَاسْتَطْعِمُونِي أُطْعِمْكُمْ. يَا عِبَادِي! كُلُّكُمْ عَارٍ إلَّا مَنْ كَسَوْته، فَاسْتَكْسُونِي أَكْسُكُمْ. يَا عِبَادِي! إنَّكُمْ تُخْطِئُونَ بِاللَّيْلِ وَالنَّهَارِ، وَأَنَا أَغْفِرُ الذُّنُوبَ جَمِيعًا؛ فَاسْتَغْفِرُونِي أَغْفِرْ لَكُمْ. يَا عِبَادِي! إنَّكُمْ لَنْ تَبْلُغُوا ضُرِّي فَتَضُرُّونِي، وَلَنْ تَبْلُغُوا نَفْعِي فَتَنْفَعُونِي. يَا عِبَادِي! لَوْ أَنَّ أَوَّلَكُمْ وَآخِرَكُمْ وَإِنْسَكُمْ وَجِنَّكُمْ كَانُوا عَلَى أَتْقَى قَلْبِ رَجُلٍ وَاحِدٍ مِنْكُمْ، مَا زَادَ ذَلِكَ فِي مُلْكِي شَيْئًا. يَا عِبَادِي! لَوْ أَنَّ أَوَّلَكُمْ وَآخِرَكُمْ وَإِنْسَكُمْ وَجِنَّكُمْ كَانُوا عَلَى أَفْجَرِ قَلْبِ رَجُلٍ وَاحِدٍ مِنْكُمْ، مَا نَقَصَ ذَلِكَ مِنْ مُلْكِي شَيْئًا. يَا عِبَادِي! لَوْ أَنَّ أَوَّلَكُمْ وَآخِرَكُمْ وَإِنْسَكُمْ وَجِنَّكُمْ قَامُوا فِي صَعِيدٍ وَاحِدٍ، فَسَأَلُونِي، فَأَعْطَيْت كُلَّ وَاحِدٍ مَسْأَلَته، مَا نَقَصَ ذَلِكَ مِمَّا عِنْدِي إلَّا كَمَا يَنْقُصُ الْمِخْيَطُ إذَا أُدْخِلَ الْبَحْرَ. يَا عِبَادِي! إنَّمَا هِيَ أَعْمَالُكُمْ أُحْصِيهَا لَكُمْ، ثُمَّ أُوَفِّيكُمْ إيَّاهَا؛ فَمَنْ وَجَدَ خَيْرًا فَلْيَحْمَدْ اللَّهَ، وَمَنْ وَجَدَ غَيْرَ ذَلِكَ فَلَا يَلُومَن إلَّا نَفْسَهُ . [رَوَاهُ مُسْلِمٌ]",
                urduTranslation = "حضرت ابوذر غفاری رضی اللہ عنہ سے روایت ہے کہ نبی کریم صلی اللہ علیہ وسلم نے اپنے رب عزوجل سے روایت کیا کہ اللہ تعالیٰ نے فرمایا: اے میرے بندو! میں نے ظلم کو اپنے اوپر حرام کر لیا ہے اور اسے تمہارے درمیان بھی حرام قرار دیا ہے، پس تم ایک دوسرے پر ظلم نہ کرو۔ اے میرے بندو! تم سب کے سب گمراہ ہو سوائے اس کے جسے میں ہدایت دوں، پس تم مجھ سے ہدایت مانگو میں تمہیں ہدایت دوں گا۔ اے میرے بندو! تم سب بھوکے ہو سوائے اس کے جسے میں کھلاؤں، پس تم مجھ سے کھانا مانگو میں تمہیں کھلاؤں گا۔ اے میرے بندو! تم سب ننگے ہو سوائے اس کے جسے میں پہناؤں، پس تم مجھ سے لباس مانگو میں تمہیں لباس دوں گا۔ اے میرے بندو! تم رات دن گناہ کرتے ہو اور میں تمام گناہوں کو بخشتا ہوں، پس تم مجھ سے مغفرت مانگو میں تمہیں بخش دوں گا۔ اے میرے بندو! تم کبھی مجھے نقصان نہیں پہنچا سکتے کہ مجھے کوئی نقصان پہنچے، اور نہ تم مجھے کوئی نفع پہنچا سکتے ہو کہ مجھے نفع پہنچے۔ اے میرے بندو! اگر تمہارے اگلے اور پچھلے، انسان اور جنات سب تم میں سے سب سے زیادہ متقی شخص کے دل جیسے ہو جائیں تو اس سے میری سلطنت و بادشاہت میں ذرہ برابر اضافہ نہیں ہوگا۔ اے میرے بندو! اگر تمہارے اگلے اور پچھلے، انسان اور جنات سب تم میں سے سب سے زیادہ بدکار شخص کے دل جیسے ہو جائیں تو اس سے میری بادشاہت میں ذرہ برابر کمی نہیں آئے گی۔ اے میرے بندو! اگر تمہارے اگلے اور پچھلے، انسان اور جنات سب ایک کھلے میدان میں کھڑے ہو کر مجھ سے مانگیں اور میں ہر انسان کو اس کا سوال عطا کر دوں، تو اس سے میرے خزانوں میں اتنی بھی کمی نہیں آئے گی جتنی سوئی کو سمندر میں ڈبو کر نکالنے سے سمندر کے پانی میں آتی ہے۔ اے میرے بندو! یہ صرف تمہارے ہی اعمال ہیں جنہیں میں تمہارے لیے شمار کرتا ہوں پھر تمہیں ان کا پورا بدلہ دیتا ہوں، پس جو شخص بھلائی پائے وہ اللہ کی حمد بیان کرے، اور جو شخص اس کے علاوہ کچھ پائے وہ اپنے آپ ہی کو ملامت کرے۔ (صحیح مسلم)",
                englishTranslation = "On the authority of Abu Dharr al-Ghifaree (may Allah be pleased with him) from the Prophet (peace and blessings of Allah be upon him) from his Lord, that He said: O My servants! I have forbidden dhulm (oppression) for Myself, and I have made it forbidden amongst you, so do not oppress one another. O My servants, all of you are astray except those whom I have guided, so seek guidance from Me and I shall guide you. O My servants, all of you are hungry except those whom I have fed, so seek food from Me and I shall feed you. O My servants, all of you are naked except those whom I have clothed, so seek clothing from Me and I shall clothe you. O My servants, you commit sins by day and by night, and I forgive all sins, so seek forgiveness from Me and I shall forgive you. O My servants, you will not attain harming Me so as to harm Me, and you will not attain benefiting Me so as to benefit Me. O My servants, if the first of you and the last of you, and the humans of you and the jinn of you, were all as pious as the most pious heart of any individual amongst you, then this would not increase My Kingdom an iota. O My servants, if the first of you and the last of you, and the humans of you and the jinn of you, were all as wicked as the most wicked heart of any individual amongst you, then this would not decrease My Kingdom an iota. O My servants, if the first of you and the last of you, and the humans of you and the jinn of you, were all to stand together in one place and ask of Me, and I were to give everyone what he requested, then that would not decrease what I Possess, except what is decreased of the ocean when a needle is dipped into it. O My servants, it is but your deeds that I account for you, and then recompense you for. So he who finds good, let him praise Allah, and he who finds other than that, let him blame no one but himself. [Muslim]",
                activeTranslation = "حضرت ابوذر غفاری رضی اللہ عنہ سے روایت ہے کہ نبی کریم صلی اللہ علیہ وسلم نے اپنے رب عزوجل سے روایت کیا کہ اللہ تعالیٰ نے فرمایا: اے میرے بندو! میں نے ظلم کو اپنے اوپر حرام کر لیا ہے اور اسے تمہارے درمیان بھی حرام قرار دیا ہے، پس تم ایک دوسرے پر ظلم نہ کرو۔ اے میرے بندو! تم سب کے سب گمراہ ہو سوائے اس کے جسے میں ہدایت دوں، پس تم مجھ سے ہدایت مانگو میں تمہیں ہدایت دوں گا۔ اے میرے بندو! تم سب بھوکے ہو سوائے اس کے جسے میں کھلاؤں، پس تم مجھ سے کھانا مانگو میں تمہیں کھلاؤں گا۔ اے میرے بندو! تم سب ننگے ہو سوائے اس کے جسے میں پہناؤں، پس تم مجھ سے لباس مانگو میں تمہیں لباس دوں گا۔ اے میرے بندو! تم رات دن گناہ کرتے ہو اور میں تمام گناہوں کو بخشتا ہوں، پس تم مجھ سے مغفرت مانگو میں تمہیں بخش دوں گا۔ اے میرے بندو! تم کبھی مجھے نقصان نہیں پہنچا سکتے کہ مجھے کوئی نقصان پہنچے، اور نہ تم مجھے کوئی نفع پہنچا سکتے ہو کہ مجھے نفع پہنچے۔ اے میرے بندو! اگر تمہارے اگلے اور پچھلے، انسان اور جنات سب تم میں سے سب سے زیادہ متقی شخص کے دل جیسے ہو جائیں تو اس سے میری سلطنت و بادشاہت میں ذرہ برابر اضافہ نہیں ہوگا۔ اے میرے بندو! اگر تمہارے اگلے اور پچھلے، انسان اور جنات سب تم میں سے سب سے زیادہ بدکار شخص کے دل جیسے ہو جائیں تو اس سے میری بادشاہت میں ذرہ برابر کمی نہیں آئے گی۔ اے میرے بندو! اگر تمہارے اگلے اور پچھلے، انسان اور جنات سب ایک کھلے میدان میں کھڑے ہو کر مجھ سے مانگیں اور میں ہر انسان کو اس کا سوال عطا کر دوں، تو اس سے میرے خزانوں میں اتنی بھی کمی نہیں آئے گی جتنی سوئی کو سمندر میں ڈبو کر نکالنے سے سمندر کے پانی میں آتی ہے۔ اے میرے بندو! یہ صرف تمہارے ہی اعمال ہیں جنہیں میں تمہارے لیے شمار کرتا ہوں پھر تمہیں ان کا پورا بدلہ دیتا ہوں، پس جو شخص بھلائی پائے وہ اللہ کی حمد بیان کرے، اور جو شخص اس کے علاوہ کچھ پائے وہ اپنے آپ ہی کو ملامت کرے۔ (صحیح مسلم)"
            ),
            Hadith(
                id = 25L,
                bookSlug = "arbaeen-nawawi",
                bookName = "40 Hadith Nawawi",
                chapterNumber = 1,
                chapterNameArabic = "الأربعون النووية",
                chapterNameUrdu = "امام نووی کی چالیس احادیث مبارکہ",
                hadithNumber = "25",
                arabicText = "عَنْ أَبِي ذَرٍّ رَضِيَ اللهُ عَنْهُ أَيْضًا، أَنَّ نَاسًا مِنْ أَصْحَابِ رَسُولِ اللَّهِ صلى الله عليه و سلم قَالُوا لِلنَّبِيِّ صلى الله عليه و سلم يَا رَسُولَ اللَّهِ ذَهَبَ أَهْلُ الدُّثُورِ بِالْأُجُورِ؛ يُصَلُّونَ كَمَا نُصَلِّي، وَيَصُومُونَ كَمَا نَصُومُ، وَيَتَصَدَّقُونَ بِفُضُولِ أَمْوَالِهِمْ. قَالَ: أَوَلَيْسَ قَدْ جَعَلَ اللَّهُ لَكُمْ مَا تَصَّدَّقُونَ؟ إنَّ بِكُلِّ تَسْبِيحَةٍ صَدَقَةً، وَكُلِّ تَكْبِيرَةٍ صَدَقَةً، وَكُلِّ تَحْمِيدَةٍ صَدَقَةً، وَكُلِّ تَهْلِيلَةٍ صَدَقَةً، وَأَمْرٌ بِمَعْرُوفٍ صَدَقَةٌ، وَنَهْيٌ عَنْ مُنْكَرٍ صَدَقَةٌ، وَفِي بُضْعِ أَحَدِكُمْ صَدَقَةٌ. قَالُوا: يَا رَسُولَ اللَّهِ أَيَأْتِي أَحَدُنَا شَهْوَتَهُ وَيَكُونُ لَهُ فِيهَا أَجْرٌ؟ قَالَ: أَرَأَيْتُمْ لَوْ وَضَعَهَا فِي حَرَامٍ أَكَانَ عَلَيْهِ وِزْرٌ؟ فَكَذَلِكَ إذَا وَضَعَهَا فِي الْحَلَالِ، كَانَ لَهُ أَجْرٌ . [رَوَاهُ مُسْلِمٌ]",
                urduTranslation = "حضرت ابوذر رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم کے اصحاب میں سے کچھ غریب لوگوں نے نبی کریم صلی اللہ علیہ وسلم سے عرض کیا: یا رسول اللہ! مالدار لوگ ثواب لوٹ کر لے گئے، وہ اسی طرح نماز پڑھتے ہیں جیسے ہم پڑھتے ہیں، اسی طرح روزے رکھتے ہیں جیسے ہم رکھتے ہیں، اور اپنے اضافی مالوں سے صدقہ بھی کرتے ہیں۔ آپ صلی اللہ علیہ وسلم نے فرمایا: کیا اللہ نے تمہارے لیے ایسی چیزیں نہیں بنائیں جن سے تم صدقہ کر سکو؟ بے شک ہر تسبیح صدقہ ہے، ہر تکبیر صدقہ ہے، ہر تحمید صدقہ ہے، ہر تہلیل صدقہ ہے، نیکی کا حکم دینا صدقہ ہے، برائی سے روکنا صدقہ ہے، اور تم میں سے کسی کا اپنی بیوی سے ازدواجی تعلق قائم کرنا بھی صدقہ ہے۔ صحابہ نے عرض کیا: یا رسول اللہ! کیا ہم میں سے کوئی اپنی خواہش پوری کرے اور اس پر بھی اسے ثواب ملے گا؟ آپ نے فرمایا: تمہارا کیا خیال ہے اگر وہ اسے کسی حرام جگہ پوری کرتا تو کیا اسے گناہ ہوتا؟ اسی طرح جب اس نے اسے حلال طریقے سے پورا کیا تو اس کے لیے ثواب ہے۔ (صحیح مسلم)",
                englishTranslation = "Also on the authority of Abu Dharr (may Allah be pleased with him): Some people from amongst the Companions of the Messenger of Allah (peace and blessings of Allah be upon him) said to the Prophet (peace and blessings of Allah be upon him), \"O Messenger of Allah, the affluent have made off with the rewards; they pray as we pray, they fast as we fast, and they give [much] in charity by virtue of their wealth.\" He (peace and blessings of Allah be upon him) said, \"Has not Allah made things for you to give in charity? Truly every tasbeehah [saying: 'subhan-Allah'] is a charity, and every takbeerah [saying: 'Allahu akbar'] is a charity, and every tahmeedah [saying: 'al-hamdu lillah'] is a charity, and every tahleelah [saying: 'laa ilaha illAllah'] is a charity. And commanding the good is a charity, and forbidding an evil is a charity, and in the bud`i [sexual act] of each one of you there is a charity.\" They said, \"O Messenger of Allah, when one of us fulfils his carnal desire will he have some reward for that?\" He (peace and blessings of Allah be upon him) said, \"Do you not see that if he were to act upon it [his desire] in an unlawful manner then he would be deserving of punishment? Likewise, if he were to act upon it in a lawful manner then he will be deserving of a reward.\" [Muslim]",
                activeTranslation = "حضرت ابوذر رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم کے اصحاب میں سے کچھ غریب لوگوں نے نبی کریم صلی اللہ علیہ وسلم سے عرض کیا: یا رسول اللہ! مالدار لوگ ثواب لوٹ کر لے گئے، وہ اسی طرح نماز پڑھتے ہیں جیسے ہم پڑھتے ہیں، اسی طرح روزے رکھتے ہیں جیسے ہم رکھتے ہیں، اور اپنے اضافی مالوں سے صدقہ بھی کرتے ہیں۔ آپ صلی اللہ علیہ وسلم نے فرمایا: کیا اللہ نے تمہارے لیے ایسی چیزیں نہیں بنائیں جن سے تم صدقہ کر سکو؟ بے شک ہر تسبیح صدقہ ہے، ہر تکبیر صدقہ ہے، ہر تحمید صدقہ ہے، ہر تہلیل صدقہ ہے، نیکی کا حکم دینا صدقہ ہے، برائی سے روکنا صدقہ ہے، اور تم میں سے کسی کا اپنی بیوی سے ازدواجی تعلق قائم کرنا بھی صدقہ ہے۔ صحابہ نے عرض کیا: یا رسول اللہ! کیا ہم میں سے کوئی اپنی خواہش پوری کرے اور اس پر بھی اسے ثواب ملے گا؟ آپ نے فرمایا: تمہارا کیا خیال ہے اگر وہ اسے کسی حرام جگہ پوری کرتا تو کیا اسے گناہ ہوتا؟ اسی طرح جب اس نے اسے حلال طریقے سے پورا کیا تو اس کے لیے ثواب ہے۔ (صحیح مسلم)"
            ),
            Hadith(
                id = 26L,
                bookSlug = "arbaeen-nawawi",
                bookName = "40 Hadith Nawawi",
                chapterNumber = 1,
                chapterNameArabic = "الأربعون النووية",
                chapterNameUrdu = "امام نووی کی چالیس احادیث مبارکہ",
                hadithNumber = "26",
                arabicText = "عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صلى الله عليه و سلم كُلُّ سُلَامَى مِنْ النَّاسِ عَلَيْهِ صَدَقَةٌ، كُلَّ يَوْمٍ تَطْلُعُ فِيهِ الشَّمْسُ تَعْدِلُ بَيْنَ اثْنَيْنِ صَدَقَةٌ، وَتُعِينُ الرَّجُلَ فِي دَابَّتِهِ فَتَحْمِلُهُ عَلَيْهَا أَوْ تَرْفَعُ لَهُ عَلَيْهَا مَتَاعَهُ صَدَقَةٌ، وَالْكَلِمَةُ الطَّيِّبَةُ صَدَقَةٌ، وَبِكُلِّ خُطْوَةٍ تَمْشِيهَا إلَى الصَّلَاةِ صَدَقَةٌ، وَتُمِيطُ الْأَذَى عَنْ الطَّرِيقِ صَدَقَةٌ .<br>[رَوَاهُ الْبُخَارِيُّ] ، [وَمُسْلِمٌ]",
                urduTranslation = "حضرت ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: انسان کے ہر جوڑ پر ہر اس دن کا صدقہ لازم ہے جس میں سورج طلوع ہوتا ہے: دو آدمیوں کے درمیان انصاف کروانا صدقہ ہے، کسی شخص کی سواری پر مدد کرنا کہ تم اسے اس پر سوار کرا دو یا اس کا سامان اس پر لاد دو یہ صدقہ ہے، پاکیزہ و اچھی بات کہنا صدقہ ہے، اور ہر وہ قدم جو تم نماز کے لیے اٹھاتے ہو صدقہ ہے، اور راستے سے تکلیف دہ چیز کو ہٹانا صدقہ ہے۔ (صحیح بخاری و صحیح مسلم)",
                englishTranslation = "On the authority of Abu Hurayrah (may Allah be pleased with him) who said: The Messenger of Allah (peace and blessings of Allah be upon him) said, “Every joint of a person must perform a charity each day that the sun rises: to judge justly between two people is a charity. To help a man with his mount, lifting him onto it or hoisting up his belongings onto it, is a charity. And the good word is a charity. And every step that you take towards the prayer is a charity, and removing a harmful object from the road is a charity.” [Al-Bukhari] [Muslim]",
                activeTranslation = "حضرت ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: انسان کے ہر جوڑ پر ہر اس دن کا صدقہ لازم ہے جس میں سورج طلوع ہوتا ہے: دو آدمیوں کے درمیان انصاف کروانا صدقہ ہے، کسی شخص کی سواری پر مدد کرنا کہ تم اسے اس پر سوار کرا دو یا اس کا سامان اس پر لاد دو یہ صدقہ ہے، پاکیزہ و اچھی بات کہنا صدقہ ہے، اور ہر وہ قدم جو تم نماز کے لیے اٹھاتے ہو صدقہ ہے، اور راستے سے تکلیف دہ چیز کو ہٹانا صدقہ ہے۔ (صحیح بخاری و صحیح مسلم)"
            ),
            Hadith(
                id = 27L,
                bookSlug = "arbaeen-nawawi",
                bookName = "40 Hadith Nawawi",
                chapterNumber = 1,
                chapterNameArabic = "الأربعون النووية",
                chapterNameUrdu = "امام نووی کی چالیس احادیث مبارکہ",
                hadithNumber = "27",
                arabicText = "عَنْ النَّوَّاسِ بْنِ سَمْعَانَ رَضِيَ اللهُ عَنْهُ عَنْ النَّبِيِّ صلى الله عليه و سلم قَالَ: \"الْبِرُّ حُسْنُ الْخُلُقِ، وَالْإِثْمُ مَا حَاكَ فِي صَدْرِك، وَكَرِهْت أَنْ يَطَّلِعَ عَلَيْهِ النَّاسُ\" رَوَاهُ مُسْلِمٌ [رَوَاهُ مُسْلِمٌ]. وَعَنْ وَابِصَةَ بْنِ مَعْبَدٍ رَضِيَ اللهُ عَنْهُ قَالَ: أَتَيْت رَسُولَ اللَّهِ صلى الله عليه و سلم فَقَالَ: \"جِئْتَ تَسْأَلُ عَنْ الْبِرِّ؟ قُلْت: نَعَمْ. فقَالَ: استفت قلبك، الْبِرُّ مَا اطْمَأَنَّتْ إلَيْهِ النَّفْسُ، وَاطْمَأَنَّ إلَيْهِ الْقَلْبُ، وَالْإِثْمُ مَا حَاكَ فِي النَّفْسِ وَتَرَدَّدَ فِي الصَّدْرِ، وَإِنْ أَفْتَاك النَّاسُ وَأَفْتَوْك\" . حَدِيثٌ حَسَنٌ، رَوَيْنَاهُ في مُسْنَدَي الْإِمَامَيْنِ أَحْمَدَ بْنِ حَنْبَلٍ [رقم:4/227]، وَالدَّارِمِيّ [2/246] بِإِسْنَادٍ حَسَنٍ",
                urduTranslation = "حضرت نواس بن سمعان رضی اللہ عنہ سے روایت ہے کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا: نیکی اچھے اخلاق کا نام ہے، اور گناہ وہ ہے جو تمہارے دل میں کھٹکے اور تمہیں یہ بات بری لگے کہ لوگ اس سے باخبر ہوں۔ اور حضرت وابصہ بن معبد رضی اللہ عنہ سے مروی ہے، انہوں نے کہا کہ میں رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوا، تو آپ نے فرمایا: تم نیکی کے بارے میں پوچھنے آئے ہو؟ میں نے کہا: جی ہاں۔ آپ صلی اللہ علیہ وسلم نے فرمایا: اپنے دل سے فتویٰ لو! نیکی وہ ہے جس پر نفس مطمئن ہو اور دل کو سکون ملے، اور گناہ وہ ہے جو دل میں کھٹکے اور سینے میں تردد پیدا کرے خواہ لوگ تمہیں بار بار فتویٰ ہی کیوں نہ دیں۔ (صحیح مسلم و مسند احمد)",
                englishTranslation = "On the authority of an-Nawas bin Sam’an (may Allah be pleased with him), that the Prophet (peace and blessings of Allah be upon him) said: Righteousness is in good character, and wrongdoing is that which wavers in your soul, and which you dislike people finding out about. [Muslim] And on the authority of Wabisah bin Ma’bad (may Allah be pleased with him) who said: I came to the Messenger of Allah (peace and blessings of Allah be upon him) and he (peace and blessings of Allah be upon him) said, “You have come to ask about righteousness.” I said, “Yes.” He (peace and blessings of Allah be upon him) said, “Consult your heart. Righteousness is that about which the soul feels at ease and the heart feels tranquil. And wrongdoing is that which wavers in the soul and causes uneasiness in the breast, even though people have repeatedly given their legal opinion [in its favour].” A good hadeeth transmitted from the musnads of the two imams, Ahmed bin Hambal and Al- Darimi, with a good chain of authorities",
                activeTranslation = "حضرت نواس بن سمعان رضی اللہ عنہ سے روایت ہے کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا: نیکی اچھے اخلاق کا نام ہے، اور گناہ وہ ہے جو تمہارے دل میں کھٹکے اور تمہیں یہ بات بری لگے کہ لوگ اس سے باخبر ہوں۔ اور حضرت وابصہ بن معبد رضی اللہ عنہ سے مروی ہے، انہوں نے کہا کہ میں رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوا، تو آپ نے فرمایا: تم نیکی کے بارے میں پوچھنے آئے ہو؟ میں نے کہا: جی ہاں۔ آپ صلی اللہ علیہ وسلم نے فرمایا: اپنے دل سے فتویٰ لو! نیکی وہ ہے جس پر نفس مطمئن ہو اور دل کو سکون ملے، اور گناہ وہ ہے جو دل میں کھٹکے اور سینے میں تردد پیدا کرے خواہ لوگ تمہیں بار بار فتویٰ ہی کیوں نہ دیں۔ (صحیح مسلم و مسند احمد)"
            ),
            Hadith(
                id = 28L,
                bookSlug = "arbaeen-nawawi",
                bookName = "40 Hadith Nawawi",
                chapterNumber = 1,
                chapterNameArabic = "الأربعون النووية",
                chapterNameUrdu = "امام نووی کی چالیس احادیث مبارکہ",
                hadithNumber = "28",
                arabicText = "عَنْ أَبِي نَجِيحٍ الْعِرْبَاضِ بْنِ سَارِيَةَ رَضِيَ اللهُ عَنْهُ قَالَ: وَعَظَنَا رَسُولُ اللَّهِ صلى الله عليه و سلم مَوْعِظَةً وَجِلَتْ مِنْهَا الْقُلُوبُ، وَذَرَفَتْ مِنْهَا الْعُيُونُ، فَقُلْنَا: يَا رَسُولَ اللَّهِ! كَأَنَّهَا مَوْعِظَةُ مُوَدِّعٍ فَأَوْصِنَا، قَالَ: أُوصِيكُمْ بِتَقْوَى اللَّهِ، وَالسَّمْعِ وَالطَّاعَةِ وَإِنْ تَأَمَّرَ عَلَيْكُمْ عَبْدٌ، فَإِنَّهُ مَنْ يَعِشْ مِنْكُمْ فَسَيَرَى اخْتِلَافًا كَثِيرًا، فَعَلَيْكُمْ بِسُنَّتِي وَسُنَّةِ الْخُلَفَاءِ الرَّاشِدِينَ الْمَهْدِيينَ، عَضُّوا عَلَيْهَا بِالنَّوَاجِذِ، وَإِيَّاكُمْ وَمُحْدَثَاتِ الْأُمُورِ؛ فَإِنَّ كُلَّ بِدْعَةٍ ضَلَالَةٌ . [رَوَاهُ أَبُو دَاوُدَ]، وَاَلتِّرْمِذِيُّ [رقم:266] وَقَالَ: حَدِيثٌ حَسَنٌ صَحِيحٌ",
                urduTranslation = "حضرت عرباض بن ساریہ رضی اللہ عنہ سے روایت ہے، انہوں نے فرمایا: رسول اللہ صلی اللہ علیہ وسلم نے ہمیں ایک ایسا دل ہلا دینے والا وعظ فرمایا جس سے آنکھیں اشکبار ہو گئیں اور دل دہل گئے۔ ہم نے عرض کیا: یا رسول اللہ! یہ تو کسی الوداع کہنے والے کا سا وعظ معلوم ہوتا ہے، پس آپ ہمیں وصیت فرمائیے۔ آپ صلی اللہ علیہ وسلم نے فرمایا: میں تمہیں اللہ کے تقویٰ کی اور سننے اور اطاعت کرنے کی وصیت کرتا ہوں خواہ تم پر کوئی حبشی غلام ہی امیر کیوں نہ بنا دیا جائے۔ اور تم میں سے جو میرے بعد زندہ رہے گا وہ بہت زیادہ اختلافات دیکھے گا، پس تم میری سنت اور ہدایت یافتہ خلفائے راشدین کی سنت کو لازم پکڑنا، اسے دانتوں سے مضبوطی سے تھامے رکھنا، اور دین میں نئی ایجاد کردہ باتوں سے بچتے رہنا، کیونکہ ہر نئی بات بدعت ہے اور ہر بدعت گمراہی ہے۔ (سنن ابوداؤد و جامع ترمذی)",
                englishTranslation = "On the authority of Abu Najeeh al-’Irbaad ibn Saariyah (may Allah be pleased with him) who said: The Messenger of Allah (peace and blessings of Allah be upon him) gave us a sermon by which our hearts were filled with fear and tears came to our eyes. So we said, “O Messenger of Allah! It is as though this is a farewell sermon, so counsel us.” He (peace and blessings of Allah be upon him) said, “I counsel you to have taqwa (fear) of Allah, and to listen and obey [your leader], even if a slave were to become your ameer. Verily he among you who lives long will see great controversy, so you must keep to my Sunnah and to the Sunnah of the Khulafa ar-Rashideen (the rightly guided caliphs), those who guide to the right way. Cling to it stubbornly [literally: with your molar teeth]. Beware of newly invented matters [in the religion], for verily every bidah (innovation) is misguidance.” [Abu Dawud] It was related by at-Tirmidhi, who said that it was a good and sound hadeeth",
                activeTranslation = "حضرت عرباض بن ساریہ رضی اللہ عنہ سے روایت ہے، انہوں نے فرمایا: رسول اللہ صلی اللہ علیہ وسلم نے ہمیں ایک ایسا دل ہلا دینے والا وعظ فرمایا جس سے آنکھیں اشکبار ہو گئیں اور دل دہل گئے۔ ہم نے عرض کیا: یا رسول اللہ! یہ تو کسی الوداع کہنے والے کا سا وعظ معلوم ہوتا ہے، پس آپ ہمیں وصیت فرمائیے۔ آپ صلی اللہ علیہ وسلم نے فرمایا: میں تمہیں اللہ کے تقویٰ کی اور سننے اور اطاعت کرنے کی وصیت کرتا ہوں خواہ تم پر کوئی حبشی غلام ہی امیر کیوں نہ بنا دیا جائے۔ اور تم میں سے جو میرے بعد زندہ رہے گا وہ بہت زیادہ اختلافات دیکھے گا، پس تم میری سنت اور ہدایت یافتہ خلفائے راشدین کی سنت کو لازم پکڑنا، اسے دانتوں سے مضبوطی سے تھامے رکھنا، اور دین میں نئی ایجاد کردہ باتوں سے بچتے رہنا، کیونکہ ہر نئی بات بدعت ہے اور ہر بدعت گمراہی ہے۔ (سنن ابوداؤد و جامع ترمذی)"
            ),
            Hadith(
                id = 29L,
                bookSlug = "arbaeen-nawawi",
                bookName = "40 Hadith Nawawi",
                chapterNumber = 1,
                chapterNameArabic = "الأربعون النووية",
                chapterNameUrdu = "امام نووی کی چالیس احادیث مبارکہ",
                hadithNumber = "29",
                arabicText = "عَنْ مُعَاذِ بْنِ جَبَلٍ رَضِيَ اللهُ عَنْهُ قَالَ: قُلْت يَا رَسُولَ اللَّهِ! أَخْبِرْنِي بِعَمَلٍ يُدْخِلُنِي الْجَنَّةَ وَيُبَاعِدْنِي مِنْ النَّارِ، قَالَ: \"لَقَدْ سَأَلْت عَنْ عَظِيمٍ، وَإِنَّهُ لَيَسِيرٌ عَلَى مَنْ يَسَّرَهُ اللَّهُ عَلَيْهِ: تَعْبُدُ اللَّهَ لَا تُشْرِكْ بِهِ شَيْئًا، وَتُقِيمُ الصَّلَاةَ، وَتُؤْتِي الزَّكَاةَ، وَتَصُومُ رَمَضَانَ، وَتَحُجُّ الْبَيْتَ، ثُمَّ قَالَ: أَلَا أَدُلُّك عَلَى أَبْوَابِ الْخَيْرِ؟ الصَّوْمُ جُنَّةٌ، وَالصَّدَقَةُ تُطْفِئُ الْخَطِيئَةَ كَمَا يُطْفِئُ الْمَاءُ النَّارَ، وَصَلَاةُ الرَّجُلِ فِي جَوْفِ اللَّيْلِ، ثُمَّ تَلَا: \" تَتَجَافَى جُنُوبُهُمْ عَنِ الْمَضَاجِعِ \" حَتَّى بَلَغَ \"يَعْمَلُونَ\"،[ 32 سورة السجدة / الأيتان : 16 و 17 ] ثُمَّ قَالَ: أَلَا أُخْبِرُك بِرَأْسِ الْأَمْرِ وَعَمُودِهِ وَذُرْوَةِ سَنَامِهِ؟ قُلْت: بَلَى يَا رَسُولَ اللَّهِ. قَالَ: رَأْسُ الْأَمْرِ الْإِسْلَامُ، وَعَمُودُهُ الصَّلَاةُ، وَذُرْوَةُ سَنَامِهِ الْجِهَادُ، ثُمَّ قَالَ: أَلَا أُخْبِرُك بِمَلَاكِ ذَلِكَ كُلِّهِ؟ فقُلْت: بَلَى يَا رَسُولَ اللَّهِ ! فَأَخَذَ بِلِسَانِهِ وَقَالَ: كُفَّ عَلَيْك هَذَا. قُلْت: يَا نَبِيَّ اللَّهِ وَإِنَّا لَمُؤَاخَذُونَ بِمَا نَتَكَلَّمُ بِهِ؟ فَقَالَ: ثَكِلَتْك أُمُّك وَهَلْ يَكُبُّ النَّاسَ عَلَى وُجُوهِهِمْ -أَوْ قَالَ عَلَى مَنَاخِرِهِمْ- إلَّا حَصَائِدُ أَلْسِنَتِهِمْ؟!\" . رَوَاهُ التِّرْمِذِيُّ [رقم:2616] وَقَالَ: حَدِيثٌ حَسَنٌ صَحِيحٌ",
                urduTranslation = "حضرت معاذ بن جبل رضی اللہ عنہ سے روایت ہے کہ میں نے عرض کیا: یا رسول اللہ! مجھے کوئی ایسا عمل بتائیے جو مجھے جنت میں داخل کر دے اور جہنم سے دور کر دے۔ آپ صلی اللہ علیہ وسلم نے فرمایا: تم نے ایک بہت بڑی بات پوچھی ہے، البتہ یہ اس شخص کے لیے آسان ہے جس کے لیے اللہ تعالیٰ اسے آسان فرما دے: تم اللہ کی عبادت کرو اور اس کے ساتھ کسی کو شریک نہ ٹھہراؤ، نماز قائم کرو، زکوٰۃ ادا کرو، رمضان کے روزے رکھو، اور بیت اللہ کا حج کرو۔ پھر فرمایا: کیا میں تمہیں بھلائی کے دروازے نہ بتاؤں؟ روزہ ڈھال ہے، اور صدقہ گناہوں کو اس طرح بجھا دیتا ہے جیسے پانی آگ کو بجھاتا ہے، اور رات کے درمیانی حصے میں بندے کا نماز پڑھنا۔ پھر آپ نے یہ آیت تلاوت فرمائی: 'تَتَجَافَى جُنُوبُهُمْ عَنِ الْمَضَاجِعِ...'۔ پھر فرمایا: کیا میں تمہیں اس دین کی اصل، اس کا ستون اور اس کی چوٹی کی بلندی نہ بتاؤں؟ میں نے کہا: کیوں نہیں، یا رسول اللہ! فرمایا: اس دین کی اصل اسلام ہے، اس کا ستون نماز ہے، اور اس کی چوٹی جہاد فی سبیل اللہ ہے۔ پھر فرمایا: کیا میں تمہیں ان تمام باتوں کا خلاصہ اور بنیاد نہ بتاؤں؟ میں نے کہا: ہاں، یا رسول اللہ! آپ نے اپنی زبان پکڑی اور فرمایا: اسے اپنے قابو میں رکھو! میں نے عرض کیا: اے اللہ کے نبی! کیا ہم جو گفتگو کرتے ہیں اس پر بھی ہماری پکڑ ہوگی؟ آپ نے فرمایا: اے معاذ! تمہاری ماں تم پر روئے! لوگ اپنی زبانوں کی کاٹی ہوئی کھیتیوں (نازیبا باتوں) کے سوا کسی اور چیز کے بل بوتے پر اوندھے منہ جہنم میں ڈالے جائیں گے! (جامع ترمذی)",
                englishTranslation = "On the authority of Muadh bin Jabal (may Allah be pleased with him) who said: I said, “O Messenger of Allah, tell me of an act which will take me into Paradise and will keep me away from the Hellfire.” He (peace and blessings of Allah be upon him) said, “You have asked me about a great matter, yet it is easy for him for whom Allah makes it easy: worship Allah, without associating any partners with Him; establish the prayer; pay the zakat; fast in Ramadhan; and make the pilgrimage to the House.” Then he (peace and blessings of Allah be upon him) said, “Shall I not guide you towards the means of goodness? Fasting is a shield; charity wipes away sin as water extinguishes fire; and the praying of a man in the depths of the night.” Then he (peace and blessings of Allah be upon him) recited: “[Those] who forsake their beds, to invoke their Lord in fear and hope, and they spend (charity in Allah’s cause) out of what We have bestowed on them. No person knows what is kept hidden for them of joy as a reward for what they used to do.” [as-Sajdah, 16-17] Then he (peace and blessings of Allah be upon him) said, “Shall I not inform you of the head of the matter, its pillar and its peak?” I said, “Yes, O Messenger of Allah.” He (peace and blessings of Allah be upon him) said, “The head of the matter is Islam, its pillar is the prayer and its peak is jihad.” Then he (peace and blessings of Allah be upon him) said, “Shall I not tell you of the foundation of all of that?” I said, “Yes, O Messenger of Allah.” So he took hold of his tongue and said, “Restrain this.” I said, “O Prophet (ﷺ) of Allah, will we be taken to account for what we say with it?” He (peace and blessings of Allah be upon him) said, “May your mother be bereaved of you, O Muadh! Is there anything that throws people into the Hellfire upon their faces — or: on their noses — except the harvests of their tongues?” It was related by at-Tirmidhi, who said it was a good and sound hadeeth",
                activeTranslation = "حضرت معاذ بن جبل رضی اللہ عنہ سے روایت ہے کہ میں نے عرض کیا: یا رسول اللہ! مجھے کوئی ایسا عمل بتائیے جو مجھے جنت میں داخل کر دے اور جہنم سے دور کر دے۔ آپ صلی اللہ علیہ وسلم نے فرمایا: تم نے ایک بہت بڑی بات پوچھی ہے، البتہ یہ اس شخص کے لیے آسان ہے جس کے لیے اللہ تعالیٰ اسے آسان فرما دے: تم اللہ کی عبادت کرو اور اس کے ساتھ کسی کو شریک نہ ٹھہراؤ، نماز قائم کرو، زکوٰۃ ادا کرو، رمضان کے روزے رکھو، اور بیت اللہ کا حج کرو۔ پھر فرمایا: کیا میں تمہیں بھلائی کے دروازے نہ بتاؤں؟ روزہ ڈھال ہے، اور صدقہ گناہوں کو اس طرح بجھا دیتا ہے جیسے پانی آگ کو بجھاتا ہے، اور رات کے درمیانی حصے میں بندے کا نماز پڑھنا۔ پھر آپ نے یہ آیت تلاوت فرمائی: 'تَتَجَافَى جُنُوبُهُمْ عَنِ الْمَضَاجِعِ...'۔ پھر فرمایا: کیا میں تمہیں اس دین کی اصل، اس کا ستون اور اس کی چوٹی کی بلندی نہ بتاؤں؟ میں نے کہا: کیوں نہیں، یا رسول اللہ! فرمایا: اس دین کی اصل اسلام ہے، اس کا ستون نماز ہے، اور اس کی چوٹی جہاد فی سبیل اللہ ہے۔ پھر فرمایا: کیا میں تمہیں ان تمام باتوں کا خلاصہ اور بنیاد نہ بتاؤں؟ میں نے کہا: ہاں، یا رسول اللہ! آپ نے اپنی زبان پکڑی اور فرمایا: اسے اپنے قابو میں رکھو! میں نے عرض کیا: اے اللہ کے نبی! کیا ہم جو گفتگو کرتے ہیں اس پر بھی ہماری پکڑ ہوگی؟ آپ نے فرمایا: اے معاذ! تمہاری ماں تم پر روئے! لوگ اپنی زبانوں کی کاٹی ہوئی کھیتیوں (نازیبا باتوں) کے سوا کسی اور چیز کے بل بوتے پر اوندھے منہ جہنم میں ڈالے جائیں گے! (جامع ترمذی)"
            ),
            Hadith(
                id = 30L,
                bookSlug = "arbaeen-nawawi",
                bookName = "40 Hadith Nawawi",
                chapterNumber = 1,
                chapterNameArabic = "الأربعون النووية",
                chapterNameUrdu = "امام نووی کی چالیس احادیث مبارکہ",
                hadithNumber = "30",
                arabicText = "عَنْ أَبِي ثَعْلَبَةَ الْخُشَنِيِّ جُرْثُومِ بن نَاشِر رَضِيَ اللهُ عَنْهُ عَنْ رَسُولِ اللَّهِ صلى الله عليه و سلم قَال: \"إنَّ اللَّهَ تَعَالَى فَرَضَ فَرَائِضَ فَلَا تُضَيِّعُوهَا، وَحَدَّ حُدُودًا فَلَا تَعْتَدُوهَا، وَحَرَّمَ أَشْيَاءَ فَلَا تَنْتَهِكُوهَا، وَسَكَتَ عَنْ أَشْيَاءَ رَحْمَةً لَكُمْ غَيْرَ نِسْيَانٍ فَلَا تَبْحَثُوا عَنْهَا\". حَدِيثٌ حَسَنٌ، رَوَاهُ الدَّارَقُطْنِيّ ْ\"في سننه\" [4/184]، وَغَيْرُهُ",
                urduTranslation = "حضرت ابو ثعلبہ خشنی رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: بے شک اللہ تعالیٰ نے کچھ فرائض مقرر فرمائے ہیں پس انہیں ضائع مت کرو، اور کچھ حدود مقرر کی ہیں پس ان سے آگے مت بڑھو، اور کچھ چیزوں کو حرام کیا ہے پس ان کا ارتکاب مت کرو، اور کچھ چیزوں کے بارے میں بغیر بھولے کے صرف تمہاری آسانی کی خاطر خاموشی اختیار فرمائی ہے پس ان کے پیچھے مت پڑو۔ (سنن دارقطنی)",
                englishTranslation = "On the authority of Abu Tha’labah al-Kushanee — Jurthoom bin Nashir (may Allah be pleased with him) — that the Messenger of Allah (peace and blessings of Allah be upon him) said: Verily Allah ta’ala has laid down religious obligations (fara’id), so do not neglect them; and He has set limits, so do not overstep them; and He has forbidden some things, so do not violate them; and He has remained silent about some things, out of compassion for you, not forgetfulness — so do not seek after them. A hasan hadeeth narrated by ad-Daraqutnee and others",
                activeTranslation = "حضرت ابو ثعلبہ خشنی رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: بے شک اللہ تعالیٰ نے کچھ فرائض مقرر فرمائے ہیں پس انہیں ضائع مت کرو، اور کچھ حدود مقرر کی ہیں پس ان سے آگے مت بڑھو، اور کچھ چیزوں کو حرام کیا ہے پس ان کا ارتکاب مت کرو، اور کچھ چیزوں کے بارے میں بغیر بھولے کے صرف تمہاری آسانی کی خاطر خاموشی اختیار فرمائی ہے پس ان کے پیچھے مت پڑو۔ (سنن دارقطنی)"
            ),
            Hadith(
                id = 31L,
                bookSlug = "arbaeen-nawawi",
                bookName = "40 Hadith Nawawi",
                chapterNumber = 1,
                chapterNameArabic = "الأربعون النووية",
                chapterNameUrdu = "امام نووی کی چالیس احادیث مبارکہ",
                hadithNumber = "31",
                arabicText = "عَنْ أَبِي الْعَبَّاسِ سَهْلِ بْنِ سَعْدٍ السَّاعِدِيّ رَضِيَ اللهُ عَنْهُ قَالَ: جَاءَ رَجُلٌ إلَى النَّبِيِّ صلى الله عليه و سلم فَقَالَ: يَا رَسُولَ اللهِ! دُلَّنِي عَلَى عَمَلٍ إذَا عَمِلْتُهُ أَحَبَّنِي اللهُ وَأَحَبَّنِي النَّاسُ؛ فَقَالَ: ازْهَدْ فِي الدُّنْيَا يُحِبَّك اللهُ، وَازْهَدْ فِيمَا عِنْدَ النَّاسِ يُحِبَّك النَّاسُ . حديث حسن، رَوَاهُ ابْنُ مَاجَهْ [رقم:4102]، وَغَيْرُهُ بِأَسَانِيدَ حَسَنَةٍ",
                urduTranslation = "حضرت سہل بن سعد ساعدی رضی اللہ عنہ سے روایت ہے کہ ایک شخص نبی کریم صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوا اور عرض کیا: یا رسول اللہ! مجھے کوئی ایسا عمل بتائیے کہ جب میں وہ کروں تو اللہ بھی مجھ سے محبت کرے اور لوگ بھی مجھ سے محبت کریں۔ آپ صلی اللہ علیہ وسلم نے فرمایا: دنیا سے بے رغبتی اختیار کرو اللہ تم سے محبت کرے گا، اور جو کچھ لوگوں کے پاس ہے اس سے بے نیازی اختیار کرو لوگ تم سے محبت کریں گے۔ (سنن ابن ماجہ)",
                englishTranslation = "On the authority of Abu al-’Abbas Sahl bin Sa’ad as-Sa’idee (may Allah be pleased with him) who said: A man came to the Prophet (peace and blessings of Allah be upon him) and said, “O Messenger of Allah, direct me to an act which, if I do it, [will cause] Allah to love me and the people to love me.” So he (peace and blessings of Allah be upon him) said, “Renounce the world and Allah will love you, and renounce what the people possess and the people will love you.” A hasan hadeeth related by Ibn Majah and others with good chains of authorities",
