                chapterNameUrdu = "امام نووی کی چالیس احادیث مبارکہ",
                hadithNumber = "38",
                arabicText = "عَنْ أَبِي هُرَيْرَة رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُول اللَّهِ صلى الله عليه و سلم إنَّ اللَّهَ تَعَالَى قَالَ: مَنْ عَادَى لِي وَلِيًّا فَقْد آذَنْتهُ بِالْحَرْبِ، وَمَا تَقَرَّبَ إلَيَّ عَبْدِي بِشَيْءٍ أَحَبَّ إلَيَّ مِمَّا افْتَرَضْتُهُ عَلَيْهِ، وَلَا يَزَالُ عَبْدِي يَتَقَرَّبُ إلَيَّ بِالنَّوَافِلِ حَتَّى أُحِبَّهُ، فَإِذَا أَحْبَبْتُهُ كُنْت سَمْعَهُ الَّذِي يَسْمَعُ بِهِ، وَبَصَرَهُ الَّذِي يُبْصِرُ بِهِ، وَيَدَهُ الَّتِي يَبْطِشُ بِهَا، وَرِجْلَهُ الَّتِي يَمْشِي بِهَا، وَلَئِنْ سَأَلَنِي لَأُعْطِيَنَّهُ، وَلَئِنْ اسْتَعَاذَنِي لَأُعِيذَنَّهُ . [رَوَاهُ الْبُخَارِيُّ]",
                urduTranslation = "حضرت ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: بے شک اللہ تعالیٰ نے فرمایا: جس نے میرے کسی ولی سے دشمنی کی تو میں نے اس کے خلاف اعلانِ جنگ کر دیا۔ اور میرا بندہ کسی ایسی چیز کے ذریعے میرا تقرب حاصل نہیں کرتا جو مجھے ان فرائض سے زیادہ محبوب ہو جو میں نے اس پر فرض کیے ہیں، اور میرا بندہ نفلی عبادتوں کے ذریعے مسلسل مجھ سے قریب ہوتا رہتا ہے یہاں تک کہ میں اس سے محبت کرنے لگتا ہوں۔ پس جب میں اس سے محبت کرتا ہوں تو میں اس کے کان بن جاتا ہوں جس سے وہ سنتا ہے، اور اس کی آنکھ بن جاتا ہوں جس سے وہ دیکھتا ہے، اور اس کا ہاتھ بن جاتا ہوں جس سے وہ پکڑتا ہے، اور اس کا پاؤں بن جاتا ہوں جس سے وہ چلتا ہے، اگر وہ مجھ سے مانگتا ہے تو میں اسے ضرور دیتا ہوں، اور اگر وہ مجھ سے پناہ مانگتا ہے تو میں اسے ضرور پناہ دیتا ہوں۔ (صحیح بخاری)",
                englishTranslation = "On the authority of Abu Hurayrah (may Allah be pleased with him) who said: The Messenger of Allah (peace and blessings of Allah be upon him) said, “Verily Allah ta’ala has said: ‘Whosoever shows enmity to a wali (friend) of Mine, then I have declared war against him. And My servant does not draw near to Me with anything more loved to Me than the religious duties I have obligated upon him. And My servant continues to draw near to me with nafil (supererogatory) deeds until I Love him. When I Love him, I am his hearing with which he hears, and his sight with which he sees, and his hand with which he strikes, and his foot with which he walks. Were he to ask [something] of Me, I would surely give it to him; and were he to seek refuge with Me, I would surely grant him refuge.’ ” [Al-Bukhari]",
                activeTranslation = "حضرت ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: بے شک اللہ تعالیٰ نے فرمایا: جس نے میرے کسی ولی سے دشمنی کی تو میں نے اس کے خلاف اعلانِ جنگ کر دیا۔ اور میرا بندہ کسی ایسی چیز کے ذریعے میرا تقرب حاصل نہیں کرتا جو مجھے ان فرائض سے زیادہ محبوب ہو جو میں نے اس پر فرض کیے ہیں، اور میرا بندہ نفلی عبادتوں کے ذریعے مسلسل مجھ سے قریب ہوتا رہتا ہے یہاں تک کہ میں اس سے محبت کرنے لگتا ہوں۔ پس جب میں اس سے محبت کرتا ہوں تو میں اس کے کان بن جاتا ہوں جس سے وہ سنتا ہے، اور اس کی آنکھ بن جاتا ہوں جس سے وہ دیکھتا ہے، اور اس کا ہاتھ بن جاتا ہوں جس سے وہ پکڑتا ہے، اور اس کا پاؤں بن جاتا ہوں جس سے وہ چلتا ہے، اگر وہ مجھ سے مانگتا ہے تو میں اسے ضرور دیتا ہوں، اور اگر وہ مجھ سے پناہ مانگتا ہے تو میں اسے ضرور پناہ دیتا ہوں۔ (صحیح بخاری)"
