                hadithNumber = "6",
                arabicText = "عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ، قَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: إِنَّ أَوَّلَ النَّاسِ يُقْضَى يَوْمَ الْقِيَامَةِ عَلَيْهِ رَجُلٌ اسْتُشْهِدَ، فَأُتِيَ بِهِ فَعَرَّفَهُ نِعَمَهُ فَعَرَفَهَا، قَالَ: فَمَا عَمِلْتَ فِيهَا؟ قَالَ قَاتَلْتُ فِيكَ حَتَّى اسْتُشْهِدْتُ، قَالَ: كَذَبْتَ، وَلَكِنَّكَ قَاتَلْتَ لِأَنْ يُقَالَ: جَرِيءٌ، فَقَدْ قِيلَ، ثُمَّ أُمِرَ بِهِ فَسُحِبَ عَلَى وَجْهِهِ حَتَّى أُلْقِيَ فِي النَّارِ. وَرَجُلٌ تَعَلَّمَ الْعِلْمَ وَعَلَّمَهُ وَقَرَأَ الْقُرْآنَ، فَأُتِيَ بِهِ، فَعَرَّفَهُ نِعَمَهُ فَعَرَفَهَا، قَالَ: فَمَا عَمِلْتَ فِيهَا؟ قَالَ: تَعَلَّمْتُ الْعِلْمَ وَعَلَّمْتُهُ، وَقَرَأْتُ فِيكَ الْقُرْآنَ، قَالَ: كَذَبْتَ، وَلَكِنَّكَ تَعَلَّمْتَ الْعِلْمَ لِيُقَالَ: عَالِمٌ، وَقَرَأْتَ الْقُرْآنَ لِيُقَالَ: هُوَ قَارِئٌ، فَقَدْ قِيلَ، ثُمَّ أُمِرَ بِهِ، فَسُحِبَ عَلَى وَجْهِهِ حَتَّى أُلْقِيَ فِي النَّارِ. وَرَجُلٌ وَسَّعَ اللَّهُ عَلَيْهِ، وَأَعْطَاهُ مِنْ أَصْنَافِ الْمَالِ كُلِّهِ، فَأُتِيَ بِهِ، فَعَرَّفَهُ نِعَمَهُ فَعَرَفَهَا، قَالَ: فَمَا عَمِلْتَ فِيهَا؟ قَالَ: مَا تَرَكْتُ مِنْ سَبِيلٍ تُحِبُّ أَنْ يُنْفَقَ فِيهَا إِلَّا أَنْفَقْتُ فِيهَا لَكَ، قَالَ: كَذَبْتَ، وَلَكِنَّكَ فَعَلْتَ لِيُقَالَ: هُوَ جَوَادٌ، فَقَدْ قِيلَ، ثُمَّ أُمِرَ بِهِ فَسُحِبَ عَلَى وَجْهِهِ، ثُمَّ أُلْقِيَ فِي النَّارِ .<br>رواه مسلم (وكذلك الترمذي والنسائي)",
                urduTranslation = "حضرت ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا: قیامت کے دن سب سے پہلے جس شخص کا فیصلہ کیا جائے گا وہ وہ شخص ہوگا جو شہید ہوا تھا، اسے لایا جائے گا اور اللہ اسے اپنی نعمتیں یاد دلائے گا تو وہ ان کا اعتراف کرے گا۔ اللہ فرمائے گا: تو نے ان نعمتوں کے بدلے کیا عمل کیا؟ وہ کہے گا: میں تیری راہ میں لڑا یہاں تک کہ شہید ہو گیا۔ اللہ فرمائے گا: تو نے جھوٹ کہا، تو اس لیے لڑا تھا تاکہ تجھے بہادر کہا جائے، سو وہ کہہ دیا گیا۔ پھر حکم دیا جائے گا اور اسے اوندھے منہ گھسیٹ کر جہنم میں ڈال دیا جائے گا۔ اور دوسرا وہ شخص جس نے علم سیکھا اور سکھایا اور قرآن پڑھا، اسے لایا جائے گا اور اللہ اپنی نعمتیں یاد دلائے گا تو وہ اعتراف کرے گا۔ اللہ فرمائے گا: تو نے کیا عمل کیا؟ وہ کہے گا: میں نے علم سیکھا، سکھایا اور تیری رضا کے لیے قرآن پڑھا۔ اللہ فرمائے گا: تو نے جھوٹ کہا، تو نے علم اس لیے سیکھا تاکہ تجھے عالم کہا جائے اور قرآن اس لیے پڑھا تاکہ تجھے قاری کہا جائے، سو وہ کہہ دیا گیا۔ پھر حکم دیا جائے گا اور اسے اوندھے منہ گھسیٹ کر جہنم میں ڈال دیا جائے گا۔ اور تیسرا وہ شخص جسے اللہ نے کشادگی دی اور ہر قسم کا مال عطا فرمایا، اسے لایا جائے گا اور اللہ اپنی نعمتیں یاد دلائے گا تو وہ اعتراف کرے گا۔ اللہ فرمائے گا: تو نے کیا عمل کیا؟ وہ کہے گا: میں نے کوئی ایسا راستہ نہیں چھوڑا جس میں خرچ کرنا تجھے پسند ہو مگر میں نے تیری رضا کے لیے خرچ کیا۔ اللہ فرمائے گا: تو نے جھوٹ کہا، تو نے اس لیے کیا تاکہ تجھے سخی کہا جائے، سو وہ کہہ دیا گیا۔ پھر حکم دیا جائے گا اور اسے اوندھے منہ گھسیٹ کر جہنم میں جھونک دیا جائے گا۔ (صحیح مسلم)",
                englishTranslation = "On the authority of Abu Hurayrah (may Allah be pleased with him), who said: I heard the Messenger of Allah (ﷺ) say: The first of people against whom judgment will be pronounced on the Day of Resurrection will be a man who died a martyr. He will be brought and Allah will make known to him His favours and he will recognize them. [ The Almighty] will say: And what did you do about them? He will say: I fought for you until I died a martyr. He will say: You have lied - you did but fight that it might be said [of you]: He is courageous. And so it was said. Then he will be ordered to be dragged along on his face until he is cast into Hell-fire. [Another] will be a man who has studied [religious] knowledge and has taught it and who used to recite the Quran. He will be brought and Allah will make known to him His favours and he will recognize them. [The Almighty] will say: And what did you do about them? He will say: I studied [religious] knowledge and I taught it and I recited the Quran for Your sake. He will say: You have lied - you did but study [religious] knowledge that it might be said [of you]: He is learned. And you recited the Quran that it might be said [of you]: He is a reciter. And so it was said. Then he will be ordered to be dragged along on his face until he is cast into Hell-fire. [Another] will be a man whom Allah had made rich and to whom He had given all kinds of wealth. He will be brought and Allah will make known to him His favours and he will recognize them. [The Almighty] will say: And what did you do about them? He will say: I left no path [untrodden] in which You like money to be spent without spending in it for Your sake. He will say: You have lied - you did but do so that it might be said [of you]: He is open-handed. And so it was said. Then he will be ordered to be dragged along on his face until he is cast into Hell-fire. It was related by Muslim (also by at-Tirmidhi and an-Nasa'i)",
                activeTranslation = "حضرت ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا: قیامت کے دن سب سے پہلے جس شخص کا فیصلہ کیا جائے گا وہ وہ شخص ہوگا جو شہید ہوا تھا، اسے لایا جائے گا اور اللہ اسے اپنی نعمتیں یاد دلائے گا تو وہ ان کا اعتراف کرے گا۔ اللہ فرمائے گا: تو نے ان نعمتوں کے بدلے کیا عمل کیا؟ وہ کہے گا: میں تیری راہ میں لڑا یہاں تک کہ شہید ہو گیا۔ اللہ فرمائے گا: تو نے جھوٹ کہا، تو اس لیے لڑا تھا تاکہ تجھے بہادر کہا جائے، سو وہ کہہ دیا گیا۔ پھر حکم دیا جائے گا اور اسے اوندھے منہ گھسیٹ کر جہنم میں ڈال دیا جائے گا۔ اور دوسرا وہ شخص جس نے علم سیکھا اور سکھایا اور قرآن پڑھا، اسے لایا جائے گا اور اللہ اپنی نعمتیں یاد دلائے گا تو وہ اعتراف کرے گا۔ اللہ فرمائے گا: تو نے کیا عمل کیا؟ وہ کہے گا: میں نے علم سیکھا، سکھایا اور تیری رضا کے لیے قرآن پڑھا۔ اللہ فرمائے گا: تو نے جھوٹ کہا، تو نے علم اس لیے سیکھا تاکہ تجھے عالم کہا جائے اور قرآن اس لیے پڑھا تاکہ تجھے قاری کہا جائے، سو وہ کہہ دیا گیا۔ پھر حکم دیا جائے گا اور اسے اوندھے منہ گھسیٹ کر جہنم میں ڈال دیا جائے گا۔ اور تیسرا وہ شخص جسے اللہ نے کشادگی دی اور ہر قسم کا مال عطا فرمایا، اسے لایا جائے گا اور اللہ اپنی نعمتیں یاد دلائے گا تو وہ اعتراف کرے گا۔ اللہ فرمائے گا: تو نے کیا عمل کیا؟ وہ کہے گا: میں نے کوئی ایسا راستہ نہیں چھوڑا جس میں خرچ کرنا تجھے پسند ہو مگر میں نے تیری رضا کے لیے خرچ کیا۔ اللہ فرمائے گا: تو نے جھوٹ کہا، تو نے اس لیے کیا تاکہ تجھے سخی کہا جائے، سو وہ کہہ دیا گیا۔ پھر حکم دیا جائے گا اور اسے اوندھے منہ گھسیٹ کر جہنم میں جھونک دیا جائے گا۔ (صحیح مسلم)"
            ),
            Hadith(
                id = 7L,
                bookSlug = "hadith-qudsi",
                bookName = "40 Hadith Qudsi",
                chapterNumber = 1,
                chapterNameArabic = "الأحاديث القدسية",
                chapterNameUrdu = "احادیث قدسیہ مبارکہ",
                hadithNumber = "7",
                arabicText = "عَنْ عُقْبَةَ بْنِ عَامِرٍ، رَضِيَ اللَّهُ عَنْهُ، قَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: يَعْجَبُ رَبُّكَ مِنْ رَاعِي غَنَمٍ، فِي رَأْسِ شَظِيَّةِ الْجَبَلِ(1)، يُؤَذِّنُ بِالصَّلَاةِ وَيُصَلِّي، فَيَقُولُ اللَّهُ، عَزَّ وَجَلَّ: انْظُرُوا إِلَى عَبْدِي هَذَا، يُؤَذِّنُ وَيُقِيمُ الصَّلَاةَ، يَخَافُ مِنِّي، قَدْ غَفَرْتُ لِعَبْدِي، وَأَدْخَلْتُهُ الْجَنَّةَ .<br>رواه النسائي بسند صحيح",
                urduTranslation = "حضرت عقبہ بن عامر رضی اللہ عنہ سے روایت ہے کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا: تمہارا رب پہاڑ کی چوٹی پر بکریاں چرانے والے چرواہے سے خوش ہوتا ہے جو نماز کے لیے اذان دیتا ہے اور نماز پڑھتا ہے، تو اللہ عزوجل فرماتا ہے: میرے اس بندے کو دیکھو! وہ اذان دیتا ہے اور نماز قائم کرتا ہے، وہ مجھ سے ڈرتا ہے، میں نے اپنے بندے کی مغفرت فرما دی اور اسے جنت میں داخل کر دیا۔ (سنن ابوداؤد و سنن نسائی)",
                englishTranslation = "On the authority of Uqbah ibn Amir (may Allah be pleased with him), who said: I heard the messenger of Allah (ﷺ) say: Your Lord delights at a shepherd who, on the peak of a mountain crag, gives the call to prayer and prays. Then Allah (glorified and exalted be He) say: Look at this servant of Mine, he gives the call to prayer and performs the prayers; he is in awe of Me. I have forgiven My servant [his sins] and have admitted him to Paradise. It was related by an-Nasa'i with a good chain of authorities",
                activeTranslation = "حضرت عقبہ بن عامر رضی اللہ عنہ سے روایت ہے کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا: تمہارا رب پہاڑ کی چوٹی پر بکریاں چرانے والے چرواہے سے خوش ہوتا ہے جو نماز کے لیے اذان دیتا ہے اور نماز پڑھتا ہے، تو اللہ عزوجل فرماتا ہے: میرے اس بندے کو دیکھو! وہ اذان دیتا ہے اور نماز قائم کرتا ہے، وہ مجھ سے ڈرتا ہے، میں نے اپنے بندے کی مغفرت فرما دی اور اسے جنت میں داخل کر دیا۔ (سنن ابوداؤد و سنن نسائی)"
            ),
            Hadith(
                id = 8L,
                bookSlug = "hadith-qudsi",
