                chapterNameArabic = "الأحاديث القدسية",
                chapterNameUrdu = "احادیث قدسیہ مبارکہ",
                hadithNumber = "8",
                arabicText = "عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ، عَنْ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: مَنْ صَلَّى صَلَاةً لَمْ يَقْرَأْ فِيهَا بِأُمِّ الْقُرْآنِ، فَهِيَ خِدَاجٌ(1) ثَلَاثًا، غَيْرَ تَمَامٍ، فَقِيلَ لِأَبِي هُرَيْرَةَ: إِنَّا نَكُونُ وَرَاءَ الْإِمَامِ، فَقَالَ: اقْرَأْ بِهَا فِي نَفْسِكَ، فَإِنِّي سَمِعْتُ النبي صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: قَالَ اللَّهُ عَزَّ وَجَلَّ: قَسَمْتُ الصَّلَاةَ بَيْنِي وَبَيْنَ عَبْدِي نِصْفَيْنِ، وَلِعَبْدِي مَا سَأَلَ، فَإِذَا قَالَ الْعَبْدُ:{ الْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ } قَالَ اللَّهُ عَزَّ وَجَلَّ: حَمِدَنِي عَبْدِي، وَإِذَا قَالَ:{ الرَّحْمَنِ الرَّحِيمِ } قَالَ اللَّهُ عَزَّ وَجَلَّ: أَثْنَى عَلَيَّ عَبْدِي، وَإِذَا قَالَ:{ مَالِكِ يَوْمِ الدِّينِ } قَالَ اللَّهُ: مَجَّدَنِي عَبْدِي - وَقَالَ مَرَّةً: فَوَّضَ إِلَيَّ عَبْدِي، فَإِذَا قَالَ:{ إِيَّاكَ نَعْبُدُ وَإِيَّاكَ نَسْتَعِينُ } قَالَ: هَذَا بَيْنِي وَبَيْنَ عَبْدِي وَلِعَبْدِي مَا سَأَلَ، فَإِذَا قَالَ:{ اهْدِنَا الصِّرَاطَ الْمُسْتَقِيمَ صِرَاطَ الَّذِينَ أَنْعَمْتَ عَلَيْهِمْ غَيْرِ الْمَغْضُوبِ عَلَيْهِمْ وَلَا الضَّالِّينَ } قَالَ: هَذَا لِعَبْدِي وَلِعَبْدِي مَا سَأَلَ .<br>رواه مسلم (وكذلك مالك والترمذي وأبو داود والنسائي وابن ماجه)",
                urduTranslation = "حضرت ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا: جس نے کوئی ایسی نماز پڑھی جس میں سورۃ فاتحہ نہ پڑھی تو وہ نماز ناقص ہے، ناقص ہے، ادھوری ہے۔ ابوہریرہ سے عرض کیا گیا: ہم امام کے پیچھے ہوتے ہیں؟ انہوں نے کہا: اسے اپنے دل میں پڑھو، کیونکہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا کہ اللہ تعالیٰ نے فرمایا: میں نے نماز (سورۃ فاتحہ) کو اپنے اور اپنے بندے کے درمیان دو برابر حصوں میں تقسیم کر دیا ہے اور میرے بندے کے لیے وہی ہے جو اس نے مانگا۔ پس جب بندہ کہتا ہے: 'الحمد للہ رب العالمین' تو اللہ فرماتا ہے: میرے بندے نے میری حمد بیان کی۔ جب کہتا ہے: 'الرحمن الرحیم' تو اللہ فرماتا ہے: میرے بندے نے میری ثنا بیان کی۔ جب وہ کہتا ہے: 'مالک یوم الدین' تو اللہ فرماتا ہے: میرے بندے نے میری بزرگی بیان کی۔ جب کہتا ہے: 'ایاک نعبد وایاک نستعین' تو اللہ فرماتا ہے: یہ میرے اور میرے بندے کے درمیان ہے اور میرے بندے کے لیے وہی ہے جو اس نے مانگا۔ اور جب کہتا ہے: 'اہدنا الصراط المستقیم صراط الذین انعمت علیہم غیر المغضوب علیہم ولا الضالین' تو اللہ فرماتا ہے: یہ میرے بندے کے لیے ہے اور میرے بندے کے لیے وہی ہے جو اس نے مانگا۔ (صحیح مسلم، ترمذی، ابوداؤد، نسائی، ابن ماجہ)",
                englishTranslation = "On the authority of Abu Hurayrah (may Allah be pleased with him) from the Prophet (ﷺ), who said: A prayer performed by someone who has not recited the Essence of the Quran (1) during it is deficient (and he repeated the word three times), incomplete. Someone said to Abu Hurayrah: [Even though] we are behind the imam? (2) He said: Recite it to yourself, for I have heard the Prophet (may the blessings and peace of Allah be up on him) say: Allah (mighty and sublime be He), had said: I have divided prayer between Myself and My servant into two halves, and My servant shall have what he has asked for. When the servant says: Al-hamdu lillahi rabbi l-alamin (3), Allah (mighty and sublime be He) says: My servant has praised Me. And when he says: Ar-rahmani r-rahim (4), Allah (mighty and sublime be He) says: My servant has extolled Me, and when he says: Maliki yawmi d-din (5), Allah says: My servant has glorified Me - and on one occasion He said: My servant has submitted to My power. And when he says: Iyyaka na budu wa iyyaka nasta in (6), He says: This is between Me and My servant, and My servant shall have what he has asked for. And when he says: Ihdina s-sirata l- mustaqim, siratal ladhina an amta alayhim ghayril-maghdubi alayhim wa la d-dallin (7), He says: This is for My servant, and My servant shall have what he has asked for. (1) Surat al-Fatihah, the first surah (chapter) of the Qur'an. (2) i.e. standing behind the imam (leader) listening to him reciting al-Fatihah. (3) \"Praise be to Allah, Lord of the Worlds.\" (4) \"The Merciful, the Compassionate\". (5) \"Master of the Day of Judgement\". (6) \"It is You we worship and it is You we ask for help\". (7) \"Guide us to the straight path, the path of those upon whom You have bestowed favors, not of those against whom You are angry, nor of those who are astray\". It was related by Muslim (also by Malik, at-Tirmidhi, Abu-Dawud, an-Nasa'i and Ibn Majah)",
                activeTranslation = "حضرت ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا: جس نے کوئی ایسی نماز پڑھی جس میں سورۃ فاتحہ نہ پڑھی تو وہ نماز ناقص ہے، ناقص ہے، ادھوری ہے۔ ابوہریرہ سے عرض کیا گیا: ہم امام کے پیچھے ہوتے ہیں؟ انہوں نے کہا: اسے اپنے دل میں پڑھو، کیونکہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا کہ اللہ تعالیٰ نے فرمایا: میں نے نماز (سورۃ فاتحہ) کو اپنے اور اپنے بندے کے درمیان دو برابر حصوں میں تقسیم کر دیا ہے اور میرے بندے کے لیے وہی ہے جو اس نے مانگا۔ پس جب بندہ کہتا ہے: 'الحمد للہ رب العالمین' تو اللہ فرماتا ہے: میرے بندے نے میری حمد بیان کی۔ جب کہتا ہے: 'الرحمن الرحیم' تو اللہ فرماتا ہے: میرے بندے نے میری ثنا بیان کی۔ جب وہ کہتا ہے: 'مالک یوم الدین' تو اللہ فرماتا ہے: میرے بندے نے میری بزرگی بیان کی۔ جب کہتا ہے: 'ایاک نعبد وایاک نستعین' تو اللہ فرماتا ہے: یہ میرے اور میرے بندے کے درمیان ہے اور میرے بندے کے لیے وہی ہے جو اس نے مانگا۔ اور جب کہتا ہے: 'اہدنا الصراط المستقیم صراط الذین انعمت علیہم غیر المغضوب علیہم ولا الضالین' تو اللہ فرماتا ہے: یہ میرے بندے کے لیے ہے اور میرے بندے کے لیے وہی ہے جو اس نے مانگا۔ (صحیح مسلم، ترمذی، ابوداؤد، نسائی، ابن ماجہ)"
            ),
            Hadith(
                id = 9L,
                bookSlug = "hadith-qudsi",
