                chapterNameArabic = "الأحاديث القدسية",
                chapterNameUrdu = "احادیث قدسیہ مبارکہ",
                hadithNumber = "9",
                arabicText = "عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: إِنَّ أَوَّلَ مَا يُحَاسَبُ بِهِ الْعَبْدُ يَوْمَ الْقِيَامَةِ مِنْ عَمَلِهِ صَلَاتُهُ. فَإِنْ صَلُحَتْ فَقَدْ أَفْلَحَ وَأَنْجَحَ، وَإِنْ فَسَدَتْ فَقَدْ خَابَ وَخَسِرَ، فَإِنْ انْتَقَصَ مِنْ فَرِيضَتِهِ شَيْءٌ، قَالَ الرَّبُّ عَزَّ وَجَلَّ: انْظُرُوا هَلْ لِعَبْدِي مِنْ تَطَوُّعٍ فَيُكَمَّلَ بِهَا مَا انْتَقَصَ مِنْ الْفَرِيضَةِ، ثُمَّ يَكُونُ سَائِرُ عَمَلِهِ عَلَى ذَلِكَ .<br>رواه الترمذي(1) وكذلك أبو داود والنسائي وابن ماجه وأحمد",
                urduTranslation = "حضرت ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: قیامت کے دن بندے کے اعمال میں سے سب سے پہلے جس چیز کا حساب لیا جائے گا وہ اس کی نماز ہے۔ اگر وہ درست نکلی تو وہ کامیاب و کامران ہو گیا، اور اگر وہ خراب نکلی تو وہ ناکام و نامراد ہو گیا۔ پس اگر اس کے فرائض میں کچھ کمی ہوئی تو رب عزوجل فرمائے گا: دیکھو کیا میرے بندے کے پاس کچھ نوافل ہیں؟ پس ان نوافل کے ذریعے اس کے فرائض کی کمی پوری کر دی جائے گی، پھر اسی طرح اس کے باقی اعمال کا حساب لیا جائے گا۔ (جامع ترمذی، ابوداؤد، نسائی، ابن ماجہ)",
                englishTranslation = "On the authority of Abu Hurayrah (may Allah be pleased with him) from the Prophet (ﷺ), who said: Allah (mighty and sublime be He) says: The first of his actions for which a servant of Allah will be held accountable on the Day of Resurrection will be his prayers. If they are in order, then he will have prospered and succeeded: and if they are wanting, then he will have failed and lost. If there is something defective in his obligatory prayers, the Lord (glorified and exalted be He) will say: See if My servant has any supererogatory prayers with which may be completed that which was defective in his obligatory prayers. Then the rest of his actions will be judged in like fashion. It was related by at-Tirmidhi (also by Abu Dawud, an-Nasa'i, Ibn Majah and Ahmad)",
                activeTranslation = "حضرت ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: قیامت کے دن بندے کے اعمال میں سے سب سے پہلے جس چیز کا حساب لیا جائے گا وہ اس کی نماز ہے۔ اگر وہ درست نکلی تو وہ کامیاب و کامران ہو گیا، اور اگر وہ خراب نکلی تو وہ ناکام و نامراد ہو گیا۔ پس اگر اس کے فرائض میں کچھ کمی ہوئی تو رب عزوجل فرمائے گا: دیکھو کیا میرے بندے کے پاس کچھ نوافل ہیں؟ پس ان نوافل کے ذریعے اس کے فرائض کی کمی پوری کر دی جائے گی، پھر اسی طرح اس کے باقی اعمال کا حساب لیا جائے گا۔ (جامع ترمذی، ابوداؤد، نسائی، ابن ماجہ)"
