                chapterNameUrdu = "احادیث قدسیہ مبارکہ",
                hadithNumber = "10",
                arabicText = "عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ، عَنْ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: يَقُولُ اللَّهُ عَزَّ وَجَلَّ: الصَّوْمُ لِي، وَأَنَا أَجْزِي بِهِ، يَدَعُ شَهْوَتَهُ وَأَكْلَهُ وَشُرْبَهُ مِنْ أَجْلِي، وَالصَّوْمُ جُنَّةٌ(1)، وَلِلصَّائِمِ فَرْحَتَانِ: فَرْحَةٌ حِينَ يُفْطِرُ، وَفَرْحَةٌ حِينَ يَلْقَى رَبَّهُ، وَلَخُلُوفُ(2) فَمِ الصَّائِمِ أَطْيَبُ عِنْدَ اللَّهِ مِنْ رِيحِ الْمِسْكِ .<br>رواه البخاري (وكذلك مسلم ومالك والترمذي النسائي وابن ماجه)",
                urduTranslation = "حضرت ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا: اللہ عزوجل فرماتا ہے: ابنِ آدم کا ہر عمل اسی کے لیے ہے سوائے روزے کے، کیونکہ روزہ خاص میرے لیے ہے اور میں ہی اس کا بدلہ دوں گا۔ اور روزہ ڈھال ہے۔ جب تم میں سے کسی کے روزے کا دن ہو تو وہ نہ فحش گوئی کرے اور نہ شور و غل کرے، اور اگر کوئی اسے گالی دے یا لڑائی کرے تو کہہ دے کہ میں روزے دار ہوں۔ قسم ہے اس ذات کی جس کے ہاتھ میں محمد کی جان ہے! روزے دار کے منہ کی بو اللہ کے نزدیک مشک کی خوشبو سے زیادہ پاکیزہ ہے، روزے دار کے لیے دو خوشیاں ہیں جن سے وہ خوش ہوتا ہے: جب وہ افطار کرتا ہے تو خوش ہوتا ہے، اور جب وہ اپنے رب سے ملاقات کرے گا تو اپنے روزے کے ثواب پر خوش ہوگا۔ (صحیح بخاری و صحیح مسلم)",
                englishTranslation = "On the authority of Abu Hurayrah (may Allah be pleased with him) from the Prophet (ﷺ), who said: Allah (mighty and sublime be He) says: Fasting is Mine and it is I who give reward for it. [A man] gives up his sexual passion, his food and his drink for my sake. Fasting is like a shield, and he who fasts has two joys: a joy when he breaks his fast and a joy when he meets his Lord. The change in the breath of the mouth of him who fasts is better in Allah's estimation than the smell of musk. It was related by al-Bukhari (also by Muslim, Malik, at-Tirmidhi, an-Nasa'i and Ibn Majah)",
                activeTranslation = "حضرت ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا: اللہ عزوجل فرماتا ہے: ابنِ آدم کا ہر عمل اسی کے لیے ہے سوائے روزے کے، کیونکہ روزہ خاص میرے لیے ہے اور میں ہی اس کا بدلہ دوں گا۔ اور روزہ ڈھال ہے۔ جب تم میں سے کسی کے روزے کا دن ہو تو وہ نہ فحش گوئی کرے اور نہ شور و غل کرے، اور اگر کوئی اسے گالی دے یا لڑائی کرے تو کہہ دے کہ میں روزے دار ہوں۔ قسم ہے اس ذات کی جس کے ہاتھ میں محمد کی جان ہے! روزے دار کے منہ کی بو اللہ کے نزدیک مشک کی خوشبو سے زیادہ پاکیزہ ہے، روزے دار کے لیے دو خوشیاں ہیں جن سے وہ خوش ہوتا ہے: جب وہ افطار کرتا ہے تو خوش ہوتا ہے، اور جب وہ اپنے رب سے ملاقات کرے گا تو اپنے روزے کے ثواب پر خوش ہوگا۔ (صحیح بخاری و صحیح مسلم)"
