                arabicText = "عَنْ أَبِي مَسْعُودٍ الْأَنْصَارِيِّ، رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: حُوسِبَ رَجُلٌ مِمَّنْ كَانَ قَبْلَكُمْ، فَلَمْ يُوجَدْ لَهُ مِنْ الْخَيْرِ شَيْءٌ، إِلَّا أَنَّهُ كَانَ يُخَالِطُ(1) النَّاسَ، وَكَانَ مُوسِرًا، فَكَانَ يَأْمُرُ غِلْمَانَهُ أَنْ يَتَجَاوَزُوا عَنْ الْمُعْسِرِ، قَالَ (2) قَالَ اللَّهُ : نَحْنُ أَحَقُّ بِذَلِكَ مِنْكَ، تَجَاوَزُوا عَنْهُ رواه مسلم (وكذلك البخاري والنسائي)",
                urduTranslation = "حضرت ابو مسعود انصاری رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: تم سے پہلے لوگوں میں سے ایک شخص کا حساب لیا گیا تو اس کے پاس کوئی نیکی نہ نکلی سوائے اس کے کہ وہ لوگوں کے ساتھ لین دین کرتا تھا اور مالدار تھا، تو وہ اپنے خادموں کو حکم دیتا تھا کہ تنگ دست اور غریب مقروضوں سے درگزر کریں۔ اللہ عزوجل نے فرمایا: ہم اس درگزر کے تم سے زیادہ حقدار ہیں، اس سے درگزر کرو اور اسے بخش دو۔ (صحیح مسلم، صحیح بخاری، سنن نسائی)",
                englishTranslation = "On the authority of Abu Mas'ud al-Ansari (may Allah be pleased with him), who said that the Messenger of Allah (ﷺ) said: A man from among those who were before you was called to account. Nothing in the way of good was found for him except that he used to have dealings with people and, being well-to-do, he would order his servants to let off the man in straitened circumstances [from repaying his debt]. He (the Prophet (ﷺ) ﷺ) said that Allah said: We are worthier than you of that (of being so generous). Let him off. It was related by Muslim (also by al-Bukhari and an-Nasa'i)",
                activeTranslation = "حضرت ابو مسعود انصاری رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: تم سے پہلے لوگوں میں سے ایک شخص کا حساب لیا گیا تو اس کے پاس کوئی نیکی نہ نکلی سوائے اس کے کہ وہ لوگوں کے ساتھ لین دین کرتا تھا اور مالدار تھا، تو وہ اپنے خادموں کو حکم دیتا تھا کہ تنگ دست اور غریب مقروضوں سے درگزر کریں۔ اللہ عزوجل نے فرمایا: ہم اس درگزر کے تم سے زیادہ حقدار ہیں، اس سے درگزر کرو اور اسے بخش دو۔ (صحیح مسلم، صحیح بخاری، سنن نسائی)"
