                chapterNameArabic = "الأحاديث القدسية",
                chapterNameUrdu = "احادیث قدسیہ مبارکہ",
                hadithNumber = "13",
                arabicText = "عَنْ عَدِيَّ بْنَ حَاتِمٍ رَضِيَ اللَّهُ عَنْهُ يَقُولُ: كُنْتُ عِنْدَ رَسُولِ اللَّهِ، صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَجَاءَهُ رَجُلَانِ: أَحَدُهُمَا يَشْكُو الْعَيْلَةَ(1)، وَالْآخَرُ يَشْكُو قَطْعَ السَّبِيلِ(2)، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: أَمَّا قَطْعُ السَّبِيلِ فَإِنَّهُ لَا يَأْتِي عَلَيْكَ إِلَّا قَلِيلٌ، حَتَّى تَخْرُجَ الْعِيرُ إِلَى مَكَّةَ بِغَيْرِ خَفِيرٍ. وَأَمَّا الْعَيْلَةُ، فَإِنَّ السَّاعَةَ لَا تَقُومُ حَتَّى يَطُوفَ أَحَدُكُمْ بِصَدَقَتِهِ، لَا يَجِدُ مَنْ يَقْبَلُهَا مِنْهُ، ثُمَّ لَيَقِفَنَّ أَحَدُكُمْ بَيْنَ يَدَيْ اللَّهِ، لَيْسَ بَيْنَهُ وَبَيْنَهُ حِجَابٌ وَلَا تَرْجُمَانٌ يُتَرْجِمُ لَهُ، ثُمَّ لَيَقُولَنَّ لَهُ: أَلَمْ أُوتِكَ مَالًا؟ فَلَيَقُولَنَّ: بَلَى، ثُمَّ لَيَقُولَنَّ: أَلَمْ أُرْسِلْ إِلَيْكَ رَسُولًا؟ فَلَيَقُولَنَّ: بَلَى، فَيَنْظُرُ عَنْ يَمِينِهِ، فَلَا يَرَى إِلَّا النَّارَ، ثُمَّ يَنْظُرُ عَنْ شِمَالِهِ، فَلَا يَرَى إِلَّا النَّارَ، فَلْيَتَّقِيَنَّ أَحَدُكُمْ النَّارَ وَلَوْ بِشِقِّ تَمْرَةٍ، فَإِنْ لَمْ يَجِدْ فَبِكَلِمَةٍ طَيِّبَةٍ .<br>رواه البخاري",
                urduTranslation = "حضرت عدی بن حاتم رضی اللہ عنہ سے روایت ہے کہ میں رسول اللہ صلی اللہ علیہ وسلم کے پاس تھا، آپ نے فرمایا: تم میں سے ہر شخص سے اس کا رب ضرور کلام فرمائے گا اس حال میں کہ اس کے اور اللہ کے درمیان کوئی ترجمان نہیں ہوگا۔ وہ اپنے دائیں جانب دیکھے گا تو اسے وہی اعمال نظر آئیں گے جو اس نے آگے بھیجے تھے، اور اپنے بائیں جانب دیکھے گا تو اسے وہی اعمال نظر آئیں گے جو اس نے آگے بھیجے تھے، اور اپنے سامنے دیکھے گا تو اسے اپنے چہرے کے سامنے آگ کے سوا کچھ دکھائی نہیں دے گا۔ پس جہنم کی آگ سے بچو خواہ کھجور کے ایک ٹکڑے کے ذریعے ہی کیوں نہ ہو، اور اگر یہ بھی نہ پاؤ تو ایک اچھی اور میٹھی بات کے ذریعے۔ (صحیح بخاری)",
                englishTranslation = "On the authority of Adiyy ibn Hatim (may Allah be pleased with him), who said: I was with the Messenger of Allah (ﷺ) and there came to him two men: one of them was complaining of penury (being very poor), while the other was complaining of brigandry (robbery). The Messenger of Allah (ﷺ) said: As for brigandry, it will be but a short time before a caravan will [be able to] go out of Mecca without a guard. As for penury, the Hour (Day of Judgement) will not arrive before one of you takes his charity around without finding anyone to accept it from him. Then (1) one of you will surely stand before Allah, there being no screen between Him and him, nor an interpreter to translate for him. Then He will say to him: Did I not bring you wealth? And he will say: Yes. Then He will say: Did I not send to you a messenger? And he will say: Yes. And he will look to his right and will see nothing but Hell-fire, then he will look to his left and will see nothing but Hell-fire, so let each of you protect himself against Hell-fire, be it with even half a date - and if he finds it not, then with a kind word. (1) i.e. at the time of the Hour. It was related by al-Bukhari",
                activeTranslation = "حضرت عدی بن حاتم رضی اللہ عنہ سے روایت ہے کہ میں رسول اللہ صلی اللہ علیہ وسلم کے پاس تھا، آپ نے فرمایا: تم میں سے ہر شخص سے اس کا رب ضرور کلام فرمائے گا اس حال میں کہ اس کے اور اللہ کے درمیان کوئی ترجمان نہیں ہوگا۔ وہ اپنے دائیں جانب دیکھے گا تو اسے وہی اعمال نظر آئیں گے جو اس نے آگے بھیجے تھے، اور اپنے بائیں جانب دیکھے گا تو اسے وہی اعمال نظر آئیں گے جو اس نے آگے بھیجے تھے، اور اپنے سامنے دیکھے گا تو اسے اپنے چہرے کے سامنے آگ کے سوا کچھ دکھائی نہیں دے گا۔ پس جہنم کی آگ سے بچو خواہ کھجور کے ایک ٹکڑے کے ذریعے ہی کیوں نہ ہو، اور اگر یہ بھی نہ پاؤ تو ایک اچھی اور میٹھی بات کے ذریعے۔ (صحیح بخاری)"
            ),
            Hadith(
                id = 14L,
                bookSlug = "hadith-qudsi",
                bookName = "40 Hadith Qudsi",
                chapterNumber = 1,
                chapterNameArabic = "الأحاديث القدسية",
                chapterNameUrdu = "احادیث قدسیہ مبارکہ",
                hadithNumber = "14",
                arabicText = "عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ، عَنْ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: إِنَّ لِلَّهِ تَبَارَكَ وَتَعَالَى مَلَائِكَةً سَيَّارَةً فُضُلًا(1)، يَتَتَبَّعُونَ مَجَالِسَ الذِّكْرِ، فَإِذَا وَجَدُوا مَجْلِسًا فِيهِ ذِكْرٌ، قَعَدُوا مَعَهُمْ، وَحَفَّ بَعْضُهُمْ بَعْضًا بِأَجْنِحَتِهِمْ، حَتَّى يَمْلَأُوا مَا بَيْنَهُمْ وَبَيْنَ السَّمَاءِ الدُّنْيَا، فَإِذَااْنْصَرَفُوا عَرَجُوا وَصَعِدُوا إِلَى السَّمَاءِ، قَالَ (2) : فَيَسْأَلُهُمْ اللَّهُ عَزَّ وَجَلَّ وَهُوَ أَعْلَمُ بِهِمْ: مِنْ أَيْنَ جِئْتُمْ؟ فَيَقُولُونَ: جِئْنَا مِنْ عِنْدِ عِبَادٍ لَكَ فِي الْأَرْضِ، يُسَبِّحُونَكَ وَيُكَبِّرُونَكَ وَيُهَلِّلُونَكَ وَيَحْمَدُونَكَ وَيَسْأَلُونَكَ، قَالَ: وَمَا يَسْأَلُونِي؟ قَالُوا يَسْأَلُونَكَ جَنَّتَكَ، قَالَ: وَهَلْ رَأَوْا جَنَّتِي؟ قَالُوا: لَا أَيْ رَبِّ، قَالَ: فَكَيْفَ لَوْ رَأَوْا جَنَّتِي! قَالُوا: وَيَسْتَجِيرُونَكَ، قَالَ: وَمِمَّ يَسْتَجِيرُونَي؟ قَالُوا: مِنْ نَارِكَ يَا رَبِّ، قَالَ: وَهَلْ رَأَوْا نَارِي؟ قَالُوا: لَا، قَالَ: فَكَيْفَ لَوْ رَأَوْا نَارِي! قَالُوا: وَيَسْتَغْفِرُونَكَ، قَالَ (1) فَيَقُولُ: قَدْ غَفَرْتُ لَهُمْ، وأَعْطَيْتُهُمْ مَا سَأَلُوا، وَأَجَرْتُهُمْ مِمَّا اسْتَجَارُوا، قَالَ(1) يَقُولُونَ: رَبِّ فِيهِمْ فُلَانٌ، عَبْدٌ خَطَّاءٌ إِنَّمَا مَرَّ فَجَلَسَ مَعَهُمْ، قَالَ(1): فَيَقُولُ: وَلَهُ غَفَرْتُ؛ هُمْ الْقَوْمُ، لَا يَشْقَى بِهِمْ جَلِيسُهُمْ رواه مسلم وكذلك البخاري والترمذي والنسائي",
                urduTranslation = "حضرت ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا: بے شک اللہ تعالیٰ کے کچھ فرشتے راستوں میں گھومتے رہتے ہیں جو ذکر کرنے والوں کو تلاش کرتے ہیں، پس جب وہ کچھ لوگوں کو پاتے ہیں جو اللہ کا ذکر کر رہے ہوتے ہیں تو وہ ایک دوسرے کو پکارتے ہیں: آؤ اپنے مقصد کی طرف! پھر فرشتے انہیں اپنے پروں سے آسمانِ دنیا تک ڈھانپ لیتے ہیں۔ ان کا رب ان سے پوچھتا ہے حالانکہ وہ ان کا حال خوب جانتا ہے: میرے بندے کیا کہہ رہے ہیں؟ فرشتے عرض کرتے ہیں: وہ تیری تسبیح، تیری تکبیر، تیری تحمید اور تیری تمجید بیان کر رہے ہیں۔ اللہ فرماتا ہے: کیا انہوں نے مجھے دیکھا ہے؟ فرشتے عرض کرتے ہیں: نہیں، واللہ انہوں نے آپ کو نہیں دیکھا۔ اللہ فرماتا ہے: اگر وہ مجھے دیکھ لیتے تو ان کا کیا حال ہوتا؟ فرشتے عرض کرتے ہیں: اگر وہ آپ کو دیکھ لیتے تو وہ آپ کی اور زیادہ عبادت کرتے، اور زیادہ بزرگی بیان کرتے اور اور زیادہ تسبیح کرتے۔ اللہ فرماتا ہے: وہ مجھ سے کیا مانگ رہے ہیں؟ فرشتے عرض کرتے ہیں: وہ آپ سے جنت مانگ رہے ہیں۔ اللہ فرماتا ہے: کیا انہوں نے جنت دیکھی ہے؟ فرشتے عرض کرتے ہیں: نہیں، یا رب! انہوں نے اسے نہیں دیکھا۔ اللہ فرماتا ہے: اگر وہ اسے دیکھ لیتے تو ان کا کیا حال ہوتا؟ فرشتے عرض کرتے ہیں: اگر وہ اسے دیکھ لیتے تو اس کی اور زیادہ حرص کرتے، اس کی اور زیادہ طلب کرتے اور اس کی اور زیادہ رغبت رکھتے۔ اللہ فرماتا ہے: وہ کس چیز سے پناہ مانگ رہے ہیں؟ فرشتے عرض کرتے ہیں: جہنم کی آگ سے۔ اللہ فرماتا ہے: کیا انہوں نے آگ کو دیکھا ہے؟ فرشتے عرض کرتے ہیں: نہیں، یا رب! انہوں نے اسے نہیں دیکھا۔ اللہ فرماتا ہے: اگر وہ اسے دیکھ لیتے تو ان کا کیا حال ہوتا؟ فرشتے عرض کرتے ہیں: اگر وہ اسے دیکھ لیتے تو اس سے اور زیادہ بھاگتے اور اور زیادہ ڈرتے۔ اللہ فرماتا ہے: میں تمہیں گواہ بناتا ہوں کہ میں نے انہیں بخش دیا۔ فرشتوں میں سے ایک فرشتہ عرض کرتا ہے: ان میں فلاں شخص ذکر کرنے والوں میں سے نہیں تھا بلکہ وہ تو کسی ضرورت سے آیا تھا۔ اللہ تعالیٰ فرماتا ہے: یہ وہ لوگ ہیں جن کے پاس بیٹھنے والا بھی محروم و بدبخت نہیں رہتا۔ (صحیح بخاری و صحیح مسلم)",
                englishTranslation = "On the authority of Abu Hurayrah (may Allah be pleased with him) from the Prophet (ﷺ), who said: Allah (glorified and exalted be He) has supernumerary angels who rove about seeking out gatherings in which Allah's name is being invoked: they sit with them and fold their wings round each other, filling that which is between them and between the lowest heaven. When [the people in the gathering] depart, [the angels] ascend and rise up to heaven. He (the Prophet (ﷺ)) said: Then Allah (mighty and sublime be He) asks them - [though] He is most knowing about them: From where have you come? And they say: We have come from some servants of Yours on Earth: they were glorifying You (Subhana llah), exalting you (Allahu akbar), witnessing that there is no god but You (La ilaha illa llah), praising You (Al-Hamdu lillah), and asking [favours] of You. He says: And what do they ask of Me? They say: They ask of You Your Paradise. He says: And have they seen My Paradise? They say: No, O Lord. He says: And how would it be were they to have seen My Paradise! They say: And they ask protection of You. He says: From what do they ask protection of Me? They say: From Your Hell-fire, O Lord. He says: And have they seen My Hell-fire? They say: NO. He says: And how would it be were they to have seen My Hell-fire: They say: And they ask for Your forgiveness. He (the Prophet (ﷺ)) said: Then He says: I have forgiven them and I have bestowed upon them what they have asked for, and I have granted them sanctuary from that from which they asked protection. He (the Prophet (ﷺ) ﷺ) said: They say: O Lord, among them is So-and-so, a much sinning servant, who was merely passing by and sat down with them. He (the Prophet (ﷺ) ﷺ) said: And He says: And to him [too] I have given forgiveness: he who sits with such people shall not suffer. It was related by Muslim (also by al-Bukhari, at-Tirmidhi, and an-Nasa'i)",
                activeTranslation = "حضرت ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا: بے شک اللہ تعالیٰ کے کچھ فرشتے راستوں میں گھومتے رہتے ہیں جو ذکر کرنے والوں کو تلاش کرتے ہیں، پس جب وہ کچھ لوگوں کو پاتے ہیں جو اللہ کا ذکر کر رہے ہوتے ہیں تو وہ ایک دوسرے کو پکارتے ہیں: آؤ اپنے مقصد کی طرف! پھر فرشتے انہیں اپنے پروں سے آسمانِ دنیا تک ڈھانپ لیتے ہیں۔ ان کا رب ان سے پوچھتا ہے حالانکہ وہ ان کا حال خوب جانتا ہے: میرے بندے کیا کہہ رہے ہیں؟ فرشتے عرض کرتے ہیں: وہ تیری تسبیح، تیری تکبیر، تیری تحمید اور تیری تمجید بیان کر رہے ہیں۔ اللہ فرماتا ہے: کیا انہوں نے مجھے دیکھا ہے؟ فرشتے عرض کرتے ہیں: نہیں، واللہ انہوں نے آپ کو نہیں دیکھا۔ اللہ فرماتا ہے: اگر وہ مجھے دیکھ لیتے تو ان کا کیا حال ہوتا؟ فرشتے عرض کرتے ہیں: اگر وہ آپ کو دیکھ لیتے تو وہ آپ کی اور زیادہ عبادت کرتے، اور زیادہ بزرگی بیان کرتے اور اور زیادہ تسبیح کرتے۔ اللہ فرماتا ہے: وہ مجھ سے کیا مانگ رہے ہیں؟ فرشتے عرض کرتے ہیں: وہ آپ سے جنت مانگ رہے ہیں۔ اللہ فرماتا ہے: کیا انہوں نے جنت دیکھی ہے؟ فرشتے عرض کرتے ہیں: نہیں، یا رب! انہوں نے اسے نہیں دیکھا۔ اللہ فرماتا ہے: اگر وہ اسے دیکھ لیتے تو ان کا کیا حال ہوتا؟ فرشتے عرض کرتے ہیں: اگر وہ اسے دیکھ لیتے تو اس کی اور زیادہ حرص کرتے، اس کی اور زیادہ طلب کرتے اور اس کی اور زیادہ رغبت رکھتے۔ اللہ فرماتا ہے: وہ کس چیز سے پناہ مانگ رہے ہیں؟ فرشتے عرض کرتے ہیں: جہنم کی آگ سے۔ اللہ فرماتا ہے: کیا انہوں نے آگ کو دیکھا ہے؟ فرشتے عرض کرتے ہیں: نہیں، یا رب! انہوں نے اسے نہیں دیکھا۔ اللہ فرماتا ہے: اگر وہ اسے دیکھ لیتے تو ان کا کیا حال ہوتا؟ فرشتے عرض کرتے ہیں: اگر وہ اسے دیکھ لیتے تو اس سے اور زیادہ بھاگتے اور اور زیادہ ڈرتے۔ اللہ فرماتا ہے: میں تمہیں گواہ بناتا ہوں کہ میں نے انہیں بخش دیا۔ فرشتوں میں سے ایک فرشتہ عرض کرتا ہے: ان میں فلاں شخص ذکر کرنے والوں میں سے نہیں تھا بلکہ وہ تو کسی ضرورت سے آیا تھا۔ اللہ تعالیٰ فرماتا ہے: یہ وہ لوگ ہیں جن کے پاس بیٹھنے والا بھی محروم و بدبخت نہیں رہتا۔ (صحیح بخاری و صحیح مسلم)"
