                chapterNumber = 1,
                chapterNameArabic = "الأحاديث القدسية",
                chapterNameUrdu = "احادیث قدسیہ مبارکہ",
                hadithNumber = "17",
                arabicText = "عَنْ أَبِي ذَرٍّ الْغِفَارِيِّ رَضِيَ اللَّهُ عَنْهُ، عَنْ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِيمَا يَرْوِيهِ عَنْ رَبِّهِ عَزَّ وَجَلَّ أَنَّهُ قَالَ: يَا عِبَادِي: إِنِّي حَرَّمْتُ الظُّلْمَ عَلَى نَفْسِي وَجَعَلْتُهُ بَيْنَكُمْ مُحَرَّمًا فَلَا تَظَالَمُوا. يَا عِبَادِي: كُلُّكُمْ ضَالٌّ إِلَّا مَنْ هَدَيْتُهُ فَاسْتَهْدُونِي أَهْدِكُمْ، يَا عِبَادِي: كُلُّكُمْ جَائِعٌ إِلَّا مَنْ أَطْعَمْتُهُ فَاسْتَطْعِمُونِي أُطْعِمْكُمْ، يَا عِبَادِي: كُلُّكُمْ عَارٍ إِلَّا مَنْ كَسَوْتُهُ فَاسْتَكْسُونِي أَكْسُكُمْ، يَا عِبَادِي: إِنَّكُمْ تُخْطِئُونَ بِاللَّيْلِ وَالنَّهَارِ، وَأَنَا أَغْفِرُ الذُّنُوبَ جَمِيعًا، فَاسْتَغْفِرُونِي أَغْفِرْ لَكُمْ. يَا عِبَادِي: إِنَّكُمْ لَنْ تَبْلُغُوا ضَرِّي فَتَضُرُّونِي، وَلَنْ تَبْلُغُوا نَفْعِي فَتَنْفَعُونِي، يَا عِبَادِي: لَوْ أَنَّ أَوَّلَكُمْ وَآخِرَكُمْ وَإِنْسَكُمْ وَجِنَّكُمْ كَانُوا عَلَى أَتْقَى قَلْبِ رَجُلٍ وَاحِدٍ مِنْكُمْ مَا زَادَ ذَلِكَ فِي مُلْكِي شَيْئًا، يَا عِبَادِي: لَوْ أَنَّ أَوَّلَكُمْ وَآخِرَكُمْ وَإِنْسَكُمْ وَجِنَّكُمْ كَانُوا عَلَى أَفْجَرِ قَلْبِ رَجُلٍ وَاحِدٍ مِنْكُمْ مَا نَقَصَ ذَلِكَ مِنْ مُلْكِي شَيْئًا، يَا عِبَادِي: لَوْ أَنَّ أَوَّلَكُمْ وَآخِرَكُمْ وَإِنْسَكُمْ وَجِنَّكُمْ قَامُوا فِي صَعِيدٍ وَاحِدٍ فَسَأَلُونِي، فَأَعْطَيْتُ كُلَّ وَاحِدٍ مَسْأَلَتَهُ، مَا نَقَصَ ذَلِكَ مِمَّا عِنْدِي إِلَّا كَمَا يَنْقُصُ الْمِخْيَطُ إِذَا أُدْخِلَ الْبَحْرَ. يَا عِبَادِي: إِنَّمَا هِيَ أَعْمَالُكُمْ أُحْصِيهَا لَكُمْ، ثُمَّ أُوَفِّيكُمْ إِيَّاهَا، فَمَنْ وَجَدَ خَيْرًا فَلْيَحْمَدْ اللَّهَ، وَمَنْ وَجَدَ غَيْرَ ذَلِكَ فَلَا يَلُومَنَّ إِلَّا نَفْسَهُ .<br>رواه مسلم (وكذلك الترمذي وابن ماجه)",
                urduTranslation = "حضرت ابوذر غفاری رضی اللہ عنہ سے روایت ہے کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا کہ اللہ تعالیٰ فرماتا ہے: اے میرے بندو! میں نے ظلم کو اپنے اوپر حرام کر لیا ہے اور اسے تمہارے درمیان بھی حرام قرار دیا ہے، پس تم ایک دوسرے پر ظلم نہ کرو... (صحیح مسلم)",
                englishTranslation = "On the authority of Abu Dharr al-Ghifari (may Allah be pleased with him) from the Prophet (ﷺ) is that among the sayings he relates from his Lord (may He be glorified) is that He said: O My servants, I have forbidden oppression for Myself and have made it forbidden amongst you, so do not oppress one another. O My servants, all of you are astray except for those I have guided, so seek guidance of Me and I shall guide you, O My servants, all of you are hungry except for those I have fed, so seek food of Me and I shall feed you. O My servants, all of you are naked except for those I have clothed, so seek clothing of Me and I shall clothe you. O My servants, you sin by night and by day, and I forgive all sins, so seek forgiveness of Me and I shall forgive you. O My servants, you will not attain harming Me so as to harm Me, and will not attain benefitting Me so as to benefit Me. O My servants, were the first of you and the last of you, the human of you and the jinn of you to be as pious as the most pious heart of any one man of you, that would not increase My kingdom in anything. O My servants, were the first of you and the last of you, the human of you and the jinn of you to be as wicked as the most wicked heart of any one man of you, that would not decrease My kingdom in anything. O My servants, were the first of you and the last of you, the human of you and the jinn of you to rise up in one place and make a request of Me, and were I to give everyone what he requested, that would not decrease what I have, any more that a needle decreases the sea if put into it. O My servants, it is but your deeds that I reckon up for you and then recompense you for, so let him who finds good, praise Allah, and let him who finds other than that, blame no one but himself. It was related by Muslim (also by at-Tirmidhi and Ibn Majah)",
                activeTranslation = "حضرت ابوذر غفاری رضی اللہ عنہ سے روایت ہے کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا کہ اللہ تعالیٰ فرماتا ہے: اے میرے بندو! میں نے ظلم کو اپنے اوپر حرام کر لیا ہے اور اسے تمہارے درمیان بھی حرام قرار دیا ہے، پس تم ایک دوسرے پر ظلم نہ کرو... (صحیح مسلم)"
            ),
            Hadith(
                id = 18L,
                bookSlug = "hadith-qudsi",
                bookName = "40 Hadith Qudsi",
                chapterNumber = 1,
                chapterNameArabic = "الأحاديث القدسية",
                chapterNameUrdu = "احادیث قدسیہ مبارکہ",
                hadithNumber = "18",
                arabicText = "عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: إِنَّ اللَّهَ عَزَّ وَجَلَّ يَقُولُ يَوْمَ الْقِيَامَةِ: يَا ابْنَ آدَمَ، مَرِضْتُ فَلَمْ تَعُدْنِي(1) قَالَ: يَا رَبِّ كَيْفَ أَعُودُكَ وَأَنْتَ رَبُّ الْعَالَمِينَ؟ قَالَ: أَمَا عَلِمْتَ أَنَّ عَبْدِي فُلَانًا مَرِضَ فَلَمْ تَعُدْهُ؟ أَمَا عَلِمْتَ أَنَّكَ لَوْ عُدْتَهُ لَوَجَدْتَنِي عِنْدَهُ. يَا ابْنَ آدَمَ: اسْتَطْعَمْتُكَ فَلَمْ تُطْعِمْنِي، قَالَ: يَا رَبِّ وَكَيْفَ أُطْعِمُكَ وَأَنْتَ رَبُّ الْعَالَمِينَ؟ قَالَ: أَمَا عَلِمْتَ أَنَّهُ اسْتَطْعَمَكَ عَبْدِي فُلَانٌ فَلَمْ تُطْعِمْهُ؟ أَمَا عَلِمْتَ أَنَّكَ لَوْ أَطْعَمْتَهُ لَوَجَدْتَ ذَلِكَ عِنْدِي. يَا ابْنَ آدَمَ: اسْتَسْقَيْتُكَ فَلَمْ تَسْقِنِي، قَالَ: يَا رَبِّ كَيْفَ أَسْقِيكَ وَأَنْتَ رَبُّ الْعَالَمِينَ؟ قَالَ اسْتَسْقَاكَ عَبْدِي فُلَانٌ فَلَمْ تَسْقِهِ، أَمَا إِنَّكَ لَوْ سَقَيْتَهُ لَوَجَدْتَ ذَلِكَ عِنْدِي رواه مسلم",
                urduTranslation = "حضرت ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: قیامت کے دن اللہ عزوجل فرمائے گا: اے آدم کے بیٹے! میں بیمار ہوا تو نے میری عیادت نہ کی؟ وہ عرض کرے گا: اے میرے رب! میں تیری عیادت کیسے کرتا جبکہ تو رب العالمین ہے؟ اللہ فرمائے گا: کیا تجھے معلوم نہیں تھا کہ میرا فلاں بندہ بیمار ہوا تھا اور تو نے اس کی عیادت نہ کی، کیا تجھے معلوم نہیں تھا کہ اگر تو اس کی عیادت کرتا تو مجھے اس کے پاس پاتا؟ اے آدم کے بیٹے! میں نے تجھ سے کھانا مانگا تو نے مجھے کھانا نہ کھلایا؟ وہ عرض کرے گا: اے میرے رب! میں تجھے کھانا کیسے کھلاتا جبکہ تو رب العالمین ہے؟ اللہ فرمائے گا: کیا تجھے معلوم نہیں تھا کہ میرے فلاں بندے نے تجھ سے کھانا مانگا تھا اور تو نے اسے کھانا نہ کھلایا، کیا تجھے معلوم نہیں تھا کہ اگر تو اسے کھانا کھلاتا تو اس کا ثواب میرے پاس پاتا؟ اے آدم کے بیٹے! میں نے تجھ سے پانی مانگا تو نے مجھے پانی نہ پلایا؟ وہ عرض کرے گا: اے میرے رب! میں تجھے پانی کیسے پلاتا جبکہ تو رب العالمین ہے؟ اللہ فرمائے گا: میرے فلاں بندے نے تجھ سے پانی مانگا تھا تو نے اسے پانی نہ پلایا، خبردار! اگر تو اسے پانی پلاتا تو اس کا ثواب میرے پاس پاتا۔ (صحیح مسلم)",
                englishTranslation = "On the authority of Abu Hurayrah (may Allah be pleased with him), who said that the Messenger of Allah (ﷺ) said: Allah (mighty and sublime be He) will say on the Day of Resurrection: O son of Adam, I fell ill and you visited Me not. He will say: O Lord, and how should I visit You when You are the Lord of the worlds? He will say: Did you not know that My servant So-and-so had fallen ill and you visited him not? Did you not know that had you visited him you would have found Me with him? O son of Adam, I asked you for food and you fed Me not. He will say: O Lord, and how should I feed You when You are the Lord of the worlds? He will say: Did you not know that My servant So-and-so asked you for food and you fed him not? Did you not know that had you fed him you would surely have found that (the reward for doing so) with Me? O son of Adam, I asked you to give Me to drink and you gave Me not to drink. He will say: O Lord, how should I give You to drink when You are the Lord of the worlds? He will say: My servant So-and-so asked you to give him to drink and you gave him not to drink. Had you given him to drink you would have surely found that with Me. It was related by Muslim",
                activeTranslation = "حضرت ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: قیامت کے دن اللہ عزوجل فرمائے گا: اے آدم کے بیٹے! میں بیمار ہوا تو نے میری عیادت نہ کی؟ وہ عرض کرے گا: اے میرے رب! میں تیری عیادت کیسے کرتا جبکہ تو رب العالمین ہے؟ اللہ فرمائے گا: کیا تجھے معلوم نہیں تھا کہ میرا فلاں بندہ بیمار ہوا تھا اور تو نے اس کی عیادت نہ کی، کیا تجھے معلوم نہیں تھا کہ اگر تو اس کی عیادت کرتا تو مجھے اس کے پاس پاتا؟ اے آدم کے بیٹے! میں نے تجھ سے کھانا مانگا تو نے مجھے کھانا نہ کھلایا؟ وہ عرض کرے گا: اے میرے رب! میں تجھے کھانا کیسے کھلاتا جبکہ تو رب العالمین ہے؟ اللہ فرمائے گا: کیا تجھے معلوم نہیں تھا کہ میرے فلاں بندے نے تجھ سے کھانا مانگا تھا اور تو نے اسے کھانا نہ کھلایا، کیا تجھے معلوم نہیں تھا کہ اگر تو اسے کھانا کھلاتا تو اس کا ثواب میرے پاس پاتا؟ اے آدم کے بیٹے! میں نے تجھ سے پانی مانگا تو نے مجھے پانی نہ پلایا؟ وہ عرض کرے گا: اے میرے رب! میں تجھے پانی کیسے پلاتا جبکہ تو رب العالمین ہے؟ اللہ فرمائے گا: میرے فلاں بندے نے تجھ سے پانی مانگا تھا تو نے اسے پانی نہ پلایا، خبردار! اگر تو اسے پانی پلاتا تو اس کا ثواب میرے پاس پاتا۔ (صحیح مسلم)"
