                chapterNameUrdu = "احادیث قدسیہ مبارکہ",
                hadithNumber = "25",
                arabicText = "عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: إِنَّ اللَّهَ عَزَّ وَجَلَّ قَالَ: مَنْ عَادَى لِي وَلِيًّا، فَقَدْ آذَنْتُهُ بِالْحَرْبِ، وَمَا تَقَرَّبَ إِلَيَّ عَبْدِي بِشَيْءٍ أَحَبَّ إِلَيَّ مِمَّا افْتَرَضْتُ عَلَيْهِ، وَمَا يَزَالُ عَبْدِي يَتَقَرَّبُ إِلَيَّ بِالنَّوَافِلِ حَتَّى أُحِبَّهُ، فَإِذَا أَحْبَبْتُهُ، كُنْتُ سَمْعَهُ الَّذِي يَسْمَعُ بِهِ، وَبَصَرَهُ الَّذِي يُبْصِرُ بِهِ، وَيَدَهُ الَّتِي يَبْطِشُ بِهَا، وَرِجْلَهُ الَّتِي يَمْشِي بِهَا، وَإِنْ سَأَلَنِي لَأُعْطِيَنَّهُ، وَلَئِنْ اسْتَعَاذَنِي لَأُعِيذَنَّهُ، وَمَا تَرَدَّدْتُ عَنْ شَيْءٍ أَنَا فَاعِلُهُ تَرَدُّدِي عَنْ نَفْسِ عَبْدِي الْمُؤْمِنِ، يَكْرَهُ الْمَوْتَ وَأَنَا أَكْرَهُ مَسَاءَتَهُ رواه البخاري",
                urduTranslation = "حضرت ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: اللہ تعالیٰ نے فرمایا: جس نے میرے کسی ولی سے دشمنی کی تو میں نے اس کے خلاف اعلانِ جنگ کر دیا، اور میرا بندہ کسی ایسی چیز کے ذریعے میرا قرب حاصل نہیں کرتا جو مجھے ان فرائض سے زیادہ محبوب ہو جو میں نے اس پر فرض کیے ہیں، اور میرا بندہ نوافل کے ذریعے مجھ سے قریب ہوتا رہتا ہے یہاں تک کہ میں اس سے محبت کرنے لگتا ہوں۔ پس جب میں اس سے محبت کرتا ہوں تو میں اس کے کان بن جاتا ہوں جس سے وہ سنتا ہے، اور اس کی آنکھ بن جاتا ہوں جس سے وہ دیکھتا ہے، اور اس کا ہاتھ بن جاتا ہوں جس سے وہ پکڑتا ہے، اور اس کا پاؤں بن جاتا ہوں جس سے وہ چلتا ہے، اگر وہ مجھ سے مانگے تو میں اسے ضرور دیتا ہوں، اور اگر وہ مجھ سے پناہ مانگے تو میں اسے ضرور پناہ دیتا ہوں۔ (صحیح بخاری)",
                englishTranslation = "On the authority of Abu Hurayrah (may Allah be pleased with him), who said that the Messenger of Allah (ﷺ) said: Allah (mighty and sublime be He) said: Whosoever shows enmity to someone devoted to Me, I shall be at war with him. My servant draws not near to Me with anything more loved by Me than the religious duties I have enjoined upon him, and My servant continues to draw near to Me with supererogatory works so that I shall love him. When I love him I am his hearing with which he hears, his seeing with which he sees, his hand with which he strikes and his foot with which he walks. Were he to ask [something] of Me, I would surely give it to him, and were he to ask Me for refuge, I would surely grant him it. I do not hesitate about anything as much as I hesitate about [seizing] the soul of My faithful servant: he hates death and I hate hurting him. It was related by al-Bukhari",
                activeTranslation = "حضرت ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: اللہ تعالیٰ نے فرمایا: جس نے میرے کسی ولی سے دشمنی کی تو میں نے اس کے خلاف اعلانِ جنگ کر دیا، اور میرا بندہ کسی ایسی چیز کے ذریعے میرا قرب حاصل نہیں کرتا جو مجھے ان فرائض سے زیادہ محبوب ہو جو میں نے اس پر فرض کیے ہیں، اور میرا بندہ نوافل کے ذریعے مجھ سے قریب ہوتا رہتا ہے یہاں تک کہ میں اس سے محبت کرنے لگتا ہوں۔ پس جب میں اس سے محبت کرتا ہوں تو میں اس کے کان بن جاتا ہوں جس سے وہ سنتا ہے، اور اس کی آنکھ بن جاتا ہوں جس سے وہ دیکھتا ہے، اور اس کا ہاتھ بن جاتا ہوں جس سے وہ پکڑتا ہے، اور اس کا پاؤں بن جاتا ہوں جس سے وہ چلتا ہے، اگر وہ مجھ سے مانگے تو میں اسے ضرور دیتا ہوں، اور اگر وہ مجھ سے پناہ مانگے تو میں اسے ضرور پناہ دیتا ہوں۔ (صحیح بخاری)"
