                hadithNumber = "26",
                arabicText = "عَنْ أَبي أُمامةَ رَضِيَ اللهُ عَنْهُ عَن النَّبِيّ صَلَّى الله عَلَيْهِ وَ سَلَّمَ قَالَ<br>قَالَ اللهُ عَزَّ وَجَلَّ : إِنَّ أَغْبَطَ أَوْلِيَائي عِنْدِي لَمُوْمِنُ خَفِيفُ الخَاذِ ذُو حَظِّ مِنَ الصَّلاةِ أَحْسَنَ عِبَادَتَ رَبِّهِ وَ أَطَاعَهُ فِي السَّرِّ وَ كَانَ غَامِضًا فِي النَّاسِ لا يُشارُ إِلَيْهِ بِالأَصابِعِ وَ كَانَ رِزْقُهُ كفافًا فَصَبَرَ عَلى ذَلِكَ ثُمَّ نَفَضَ بِيَدِهِ ثُمَّ قَالَ : عُجِّلَتْ مَنِيَّتُهُ قَلَّتْ بَواكِيهِ قَلَّ تُرَاثُهُ<br>رواه الترمذي (وكذالك أحمد و ابن ماجه) وإسنَاده حسن",
                urduTranslation = "حضرت ابو امامہ باہلی رضی اللہ عنہ سے روایت ہے کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا: اللہ عزوجل نے فرمایا: میرے نزدیک میرے دوستوں میں سب سے زیادہ قابل رشک وہ مومن ہے جس کا بوجھ ہلکا ہو، نماز میں اس کا وافر حصہ ہو، اس نے اپنے رب کی بہترین عبادت کی ہو، اور تنہائی میں اس کی اطاعت کی ہو، وہ لوگوں میں گمنام ہو اور انگلیوں سے اس کی طرف اشارے نہ کیے جاتے ہوں، اس کا رزق بس گزر بسر کے مطابق ہو اور اس نے اس پر صبر کیا ہو۔ پھر آپ نے انگلیاں چٹخائیں اور فرمایا: اس کی موت جلدی آ جائے، اس پر رونے والیاں کم ہوں، اور اس کا ترکہ و میراث تھوڑی ہو۔ (جامع ترمذی، مسند احمد، سنن ابن ماجہ)",
                englishTranslation = "On the authority of Abu Umamah (may Allah be pleased with him), who said that the Messenger of Allah (ﷺ) said: Allah (mighty and sublime be He) said: Truly of those devoted to Me the one I most favor is a believer who is of meager means and much given to prayer, who has been particular in the worship of his Lord and has obeyed Him inwardly[1], who was obscure among people and not pointed out, and whose sustenance was just sufficient to provide for him yet he bore this patiently. Then the Prophet (ﷺ) shook his hand and said: Death will have come early to him, his mourners will have been few, his estate scant. [1] i.e. he has not been ostentatious in his obedience. It was related by at-Tirmidhi (also by Ahmad ibn Hanbal and Ibn Majah). Its chain of authorities is sound",
                activeTranslation = "حضرت ابو امامہ باہلی رضی اللہ عنہ سے روایت ہے کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا: اللہ عزوجل نے فرمایا: میرے نزدیک میرے دوستوں میں سب سے زیادہ قابل رشک وہ مومن ہے جس کا بوجھ ہلکا ہو، نماز میں اس کا وافر حصہ ہو، اس نے اپنے رب کی بہترین عبادت کی ہو، اور تنہائی میں اس کی اطاعت کی ہو، وہ لوگوں میں گمنام ہو اور انگلیوں سے اس کی طرف اشارے نہ کیے جاتے ہوں، اس کا رزق بس گزر بسر کے مطابق ہو اور اس نے اس پر صبر کیا ہو۔ پھر آپ نے انگلیاں چٹخائیں اور فرمایا: اس کی موت جلدی آ جائے، اس پر رونے والیاں کم ہوں، اور اس کا ترکہ و میراث تھوڑی ہو۔ (جامع ترمذی، مسند احمد، سنن ابن ماجہ)"
