                chapterNameUrdu = "احادیث قدسیہ مبارکہ",
                hadithNumber = "27",
                arabicText = "عَنْ مَسْرُوقٍ . قَالَ : سَأَلْنَا ـ أَوْ سَأَلْتُ عَبْدَاللهِ (أَيْ ابْنَ مَسْعُودٍ ) عَنْ هَذِهِ الايةِ :<br>: ولَا تَحْسَبَنَّ الَّذِينَ قُتِلُوا في سَبِيلِ اللهِ أَمْواتاً بَلْ أَحْياءُ عِنْدَ رَبِّهِمْ يُرْزَقُونَ )) ـ قَالَ : أَمَا إِنَّا قَدْ سَأَلْنَا عَنْ ذَلِكَ ، فَقَالَ))<br>أَرْواحُهُمْ في جَوْفِ طَيْرٍ خُضْرٍ ، لَهَا قَنَادِيلُ مُعَلَّقَةٌ بِالعَرْشِ ، تَسْرَحُ مِنَ الجَنَّةِ حَيْثُ شَاءَتْ ، ثُمَّ َ تَأْوِي إِلي تِلْكَ القَنَادِيلِ ، فَأَطَّلَعَ إِلَيْهِمْ رَبُّهُمْ اطِّلَاعَةً فَقَالَ : هَلْ تَشْتَهُونَ شَيْئاً ؟ قَالُوا : أَيَّ شَيْءٍ نَشْتَهِي ، وَ نَحْنُ نَسْرَحُ مِنَ الجَنَّةِ حَيْثُ شِئْنا ؟ فَفَعَلَ ذَلِكَ بِهِمْ ثَلَاثََ مَرَّاتٍ ، فَلَمَّا رَأَوْا أَنَّهُمْ لَنْ يُتْرَكُوا مِنْ أَنْ يُسْأَلُوا ، قَالُوا : يَا رَبِّ ، نُرِيْدُ أَنْ تَرُدَّ أَرْوَاحَنَا في أَجْسَادِنَا ؛ حَتَّى نُقْتَلَ في سَبِيلِكَ مَرَّةً أُخْرَي . فَلَمَّا رَأَى أَنْ لَيْسَ لَهُمْ حَاجَةٌ تُرِكُوا .<br>(رواهُ مسلم (وكذلك الترمذي والنسائي وابن ماجه)",
                urduTranslation = "حضرت مسروق رحمہ اللہ سے روایت ہے کہ ہم نے حضرت عبداللہ بن مسعود رضی اللہ عنہ سے اس آیت کے بارے میں پوچھا: 'وَلَا تَحْسَبَنَّ الَّذِينَ قُتِلُوا فِي سَبِيلِ اللَّهِ أَمْوَاتًا...' (اور جو لوگ اللہ کی راہ میں مارے گئے انہیں ہرگز مردہ نہ سمجھو)۔ تو انہوں نے فرمایا: ہم نے رسول اللہ صلی اللہ علیہ وسلم سے اس کے بارے میں پوچھا تھا تو آپ نے فرمایا: شہداء کی روحیں سبز پرندوں کے پیٹوں میں ہوتی ہیں، ان کے لیے عرش کے ساتھ قندیلیں لٹکی ہوئی ہیں، وہ جنت میں جہاں چاہیں چرتی چگتی ہیں پھر ان قندیلوں میں واپس آ کر بسیرا کرتی ہیں۔ ان کے رب نے ان کی طرف ایک نظر التفات فرمائی اور پوچھا: کیا تم کسی چیز کی خواہش رکھتے ہو؟ انہوں نے عرض کیا: ہم کس چیز کی خواہش کریں جبکہ ہم جنت میں جہاں چاہیں سیر کرتے ہیں! اللہ نے ان سے تین مرتبہ یہی پوچھا۔ جب انہوں نے دیکھا کہ انہیں سوال کیے بغیر نہیں چھوڑا جائے گا تو انہوں نے عرض کیا: اے ہمارے رب! ہم چاہتے ہیں کہ تو ہماری روحیں ہمارے جسموں میں واپس لوٹا دے تاکہ ہم تیری راہ میں ایک بار پھر شہید ہو جائیں۔ پس جب اللہ نے دیکھا کہ انہیں کوئی حاجت نہیں تو انہیں چھوڑ دیا گیا۔ (صحیح مسلم، ترمذی، نسائی، ابن ماجہ)",
                englishTranslation = "On the authority of Masruq, who said: We asked Abdullah (i.e. Ibn Masud) about this verse: And do not regard those who have been killed in the cause of Allah as dead, rather are they alive with their Lord, being provided for (Quran 3:169). He said: We asked about that and the Prophet (ﷺ) said: Their souls are in the insides of green birds having lanterns suspended from the Throne, roaming freely in Paradise where they please, then taking shelter in those lanterns. So their Lord cast a glance at them (1) and said: Do you wish for anything? They said: What shall we wish for when we roam freely in Paradise where we please? And thus did He do to them three times. When they say that they would not be spared from being asked [again], they said: O Lord, we would like for You to put back our souls into our bodies so that we might fight for Your sake once again. And when He saw that they were not in need of anything they were let be. (1) i.e. at those who had been killed in the cause of Allah. It was related by Muslim (also by at-Tirmidhi, an-Nasa'i and Ibn Majah)",
                activeTranslation = "حضرت مسروق رحمہ اللہ سے روایت ہے کہ ہم نے حضرت عبداللہ بن مسعود رضی اللہ عنہ سے اس آیت کے بارے میں پوچھا: 'وَلَا تَحْسَبَنَّ الَّذِينَ قُتِلُوا فِي سَبِيلِ اللَّهِ أَمْوَاتًا...' (اور جو لوگ اللہ کی راہ میں مارے گئے انہیں ہرگز مردہ نہ سمجھو)۔ تو انہوں نے فرمایا: ہم نے رسول اللہ صلی اللہ علیہ وسلم سے اس کے بارے میں پوچھا تھا تو آپ نے فرمایا: شہداء کی روحیں سبز پرندوں کے پیٹوں میں ہوتی ہیں، ان کے لیے عرش کے ساتھ قندیلیں لٹکی ہوئی ہیں، وہ جنت میں جہاں چاہیں چرتی چگتی ہیں پھر ان قندیلوں میں واپس آ کر بسیرا کرتی ہیں۔ ان کے رب نے ان کی طرف ایک نظر التفات فرمائی اور پوچھا: کیا تم کسی چیز کی خواہش رکھتے ہو؟ انہوں نے عرض کیا: ہم کس چیز کی خواہش کریں جبکہ ہم جنت میں جہاں چاہیں سیر کرتے ہیں! اللہ نے ان سے تین مرتبہ یہی پوچھا۔ جب انہوں نے دیکھا کہ انہیں سوال کیے بغیر نہیں چھوڑا جائے گا تو انہوں نے عرض کیا: اے ہمارے رب! ہم چاہتے ہیں کہ تو ہماری روحیں ہمارے جسموں میں واپس لوٹا دے تاکہ ہم تیری راہ میں ایک بار پھر شہید ہو جائیں۔ پس جب اللہ نے دیکھا کہ انہیں کوئی حاجت نہیں تو انہیں چھوڑ دیا گیا۔ (صحیح مسلم، ترمذی، نسائی، ابن ماجہ)"
