                chapterNameUrdu = "احادیث قدسیہ مبارکہ",
                hadithNumber = "33",
                arabicText = "عَنْ أَبي هُرَيْرَةَ ، رَضِيَ اللهُ عَنْهُ ، عَنِ النَّبَيِّ صَلَّى الله عَلَيْهِ وَ سَلَّمَ ، فِيما يَحْكِي عَنْ رَبِّهِ عَزَّ وَجَلَّ ، قَالَ : أَذْنَبَ عَبْدٌ ذَنْبًا ، فَقَالَ : اللَّهُمَّ اغْفِرْ لِي ذَنْبي . فَقَالَ تَبَارَكَ وَتَعَالى : أَذْنَبَ عَبْدِي ذَنْبًا ، فَعَلِمَ أنَّ لَهُ رَبّاً ، يَغْفِرُ الذَّنْبَ ، وَيَأْخُذُ بِهِ . ثُمَّ عَادَ فَأَذْنَبَ ، فَقَالَ : أَيّ رَبِّ ، اغْفِرْ لِي ذَنْبِِي ، فَقَالَ تَبَارَكَ وتَعَالى : عَبْدِي أَذْنَبَ ذَنْباً . فَعَلِمَ أَنَّ لَهُ رَبّاً يَغْفِرُ الذَّنْبَ ، ويَأْخُذُ بِهِ . ثُمَّ عَادَ فَأَذْنَبَ ، فَقَالَ : أَيّ رَبِّ ، اغْفِرْ لِي ذَنْبِي : فَقَالَ تَبَارَكَ وَتَعَالَى : أَذْنَبَ عَبْدِي ذَنْباً ، فَعَلِمَ أَنَّ لَهُ رَبّاً ، يَغْفِرُ الذَّنْبَ ، ويَأْخُذُ بالذَّنْبِ . اعْمَلْ مَا شِئْتَ ، فَقَدْ غَفَرْتُ لَكَ . رواهُ مسلم (وكذلك البخاري)",
                urduTranslation = "حضرت ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا: اللہ تعالیٰ فرماتا ہے: اے ابنِ آدم! تو میری عبادت کے لیے فارغ ہو جا، میں تیرے سینے کو غنا اور بے نیازی سے بھر دوں گا اور تیری محتاجی کا دروازہ بند کر دوں گا، اور اگر تو نے ایسا نہ کیا تو میں تیرے ہاتھوں کو دنیا کے کاموں اور مصروفیات سے بھر دوں گا اور تیری فقیری و محتاجی کو دور نہیں کروں گا۔ (جامع ترمذی و سنن ابن ماجہ)",
                englishTranslation = "On the authority of Abu Hurayrah (may Allah be pleased with him) that the Prophet (ﷺ), from among the things he reports from his Lord (mighty and sublime be He), is that he said: A servant [of Allah's] committed a sin and said: O Allah, forgive me my sin. And He (glorified and exalted be He) said: My servant has committed a sin and has known that he has a Lord who forgives sins and punishes for them. Then he sinned again and said: O Lord, forgive me my sin. And He (glorified and exalted be He) said: My servant has committed a sin and has known that he has a Lord who forgives sins and punishes for them. Then he sinned again and said: O Lord, forgive me my sin. And He (glorified and exalted be He) said: My servant has committed a sin and has known that he has a Lord who forgives sins and punishes for sins. Do what you wish, for I have forgiven you. It was related by Muslim (also by al-Bukhari)",
                activeTranslation = "حضرت ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا: اللہ تعالیٰ فرماتا ہے: اے ابنِ آدم! تو میری عبادت کے لیے فارغ ہو جا، میں تیرے سینے کو غنا اور بے نیازی سے بھر دوں گا اور تیری محتاجی کا دروازہ بند کر دوں گا، اور اگر تو نے ایسا نہ کیا تو میں تیرے ہاتھوں کو دنیا کے کاموں اور مصروفیات سے بھر دوں گا اور تیری فقیری و محتاجی کو دور نہیں کروں گا۔ (جامع ترمذی و سنن ابن ماجہ)"
            ),
            Hadith(
