    fun getQudsiHadiths(): List<Hadith> = getQudsiPart1() + getQudsiPart2()

    fun getHadithsForBook(bookSlug: String): List<Hadith> {
        return when {
            bookSlug.contains("nawawi") -> getNawawiHadiths()
            bookSlug.contains("qudsi") -> getQudsiHadiths()
            else -> emptyList()
        }
    }
